import type { DailyVerse } from "@shared/schema";

export const versesHT: DailyVerse[] = [
  { id: "1", verse: "Paske Bondye tèlman renmen lèzòm li bay sèl Pitit li a, pou tout moun ki kwè nan li pa peri, men pou yo gen lavi ki p ap janm fini an.", reference: "Jan 3:16", devotional: "Lanmou Bondye pou ou depase tout sa ou ka imajine. Li bay sa ki pi presye pou ou ka viv avèk li pou tout tan. Kite verite sa a ranpli kè ou ak rekonesans jodi a.", prayer: "Senyè, mèsi pou lanmou enkilab ou a. Ede m resevwa li nèt e pataje li ak lòt moun. Nan non Jezi, Amèn.", date: "" },
  { id: "2", verse: "Paske mwen konnen sa m gen nan tèt mwen pou nou, se Senyè a ki di sa: se byen m ap chache fè nou, pa malè. M ap fè nou gen yon bèl avni, yon bèl espwa.", reference: "Jeremi 29:11", devotional: "Bondye gen yon bèl plan pou lavi ou. Menm lè sikonstans yo parèt ensèten, fè konfyans ke li ap travay tout bagay ansanm pou byen ou. Plan li yo plen ak espwa.", prayer: "Papa ki nan syèl la, mèsi pou plan ou genyen pou mwen. Ede m fè ou konfyans menm lè m pa ka wè chemen an devan m. Nan non Jezi, Amèn.", date: "" },
  { id: "3", verse: "Senyè a se gadò mwen, mwen p ap janm manke anyen. Li fè m kouche sou zèb vèt. Li mennen m bò dlo ki kalm. Li restore nanm mwen.", reference: "Sòm 23:1-3", devotional: "Bon Gadò nou an bay tout sa nou bezwen. Li mennen nou nan kote repo ak restorasyon. Lè lavi a santi l twòp, sonje li toujou ap gide ou nan lapè.", prayer: "Senyè, ou se Gadò mwen. Mennen m nan kote repo ak lapè. Restore nanm mwen e renouvle fòs mwen. Amèn.", date: "" },
  { id: "4", verse: "Mete tout konfyans ou nan Senyè a. Pa konte sou sa ou konnen. Toujou chonje Senyè a nan tou sa w ap fè, li menm l a moutre ou chemen pou ou pran.", reference: "Pwovèb 3:5-6", devotional: "Bondye envite nou fè li konfyans totalman, san nou pa konte sou pwòp entèlijans nou. Lè nou soumèt plan nou yo ba li, li gide pa nou yo ak sajès pafè.", prayer: "Papa, mwen chwazi fè ou konfyans ak tout kè m. Gide pa m jodi a e fè chemen m dwat. Amèn.", date: "" },
  { id: "5", verse: "Mwen kapab fè tout bagay gras a Kris la ki ban m fòs.", reference: "Filipyen 4:13", devotional: "Fòs ou pa soti nan tèt pa ou men nan Kris ki ap viv nan ou. Pa gen defi ki twò gwo lè ou konte sou pouvwa li. Li ekipe ou pou chak travay li rele ou fè.", prayer: "Jezi, mèsi paske ou se fòs mwen. Ede m konte sou ou nan chak defi m ap fè fas jodi a. Amèn.", date: "" },
  { id: "6", verse: "Nou konnen Bondye ap travay nan tout bagay pou byen moun ki renmen li yo, moun li rele dapre volonte li.", reference: "Women 8:28", devotional: "Menm nan sezon difisil yo, Bondye ap travay dèyè sèn nan pou byen ou. Anyen nan lavi ou pa pèdi lè ou mete li nan men li. Fè konfyans nan pwosesis li ak lè li.", prayer: "Senyè, ede m fè konfyans ke ou ap travay tout bagay pou byen mwen, menm lè m pa ka wè sa. Amèn.", date: "" },
  { id: "7", verse: "Pran kouraj, kenbe fèm. Pa pè, pa dekouraje, paske Senyè a, Bondye ou la, ap toujou la avèk ou tout kote ou prale.", reference: "Jozye 1:9", devotional: "Bondye kòmande kouraj paske li pwomèt prezans li. Ou pa janm fè fas ak okenn sitiyasyon poukont ou. Kreyatè linivè a ap mache bò kote ou chak pa.", prayer: "Papa, ranpli m ak kouraj e fòs. Mèsi paske ou toujou la avèk mwen. Retire laperèz ak dekourajman nan kè m. Amèn.", date: "" },
  { id: "8", verse: "Senyè a se limyè mwen, se li ki delivrans mwen. Ki moun mwen ta dwe pè? Senyè a se sitadèl lavi m. Ki moun ki ta fè m tranble?", reference: "Sòm 27:1", devotional: "Lè Bondye se limyè ou, okenn fènwa pa ka genyen ou. Lè li se delivrans ou, okenn ènmi pa ka bat ou. Kanpe fèm nan konfyans ke li se pwotektè ou ak refij ou.", prayer: "Senyè, ou se limyè m ak delivrans mwen. Retire tout laperèz nan kè m epi ede m fè konfyans nan pwoteksyon ou. Amèn.", date: "" },
  { id: "9", verse: "Men moun ki mete espwa yo nan Senyè a ap jwenn fòs ankò. Y ap monte ak zèl tankou èg. Y ap kouri san yo pa fatige, y ap mache san yo pa lage.", reference: "Ezayi 40:31", devotional: "Lè ou santi ou fatige e fèb, mete espwa ou nan Bondye. Li pwomèt renouvle fòs ou yon fason sinatirèl. Tann sou li epi gade li leve ou anwo sikonstans ou yo.", prayer: "Senyè, mwen mete espwa m nan ou. Renouvle fòs mwen jodi a. Ede m vole anwo defi m yo sou zèl lafwa. Amèn.", date: "" },
  { id: "10", verse: "Vin jwenn mwen, nou tout ki bouke, ki gen chay sou do nou, m a ban nou repo.", reference: "Matye 11:28", devotional: "Jezi bay yon envitasyon pèsonèl pou depoze chay ou nan pye li. Ou pa oblije pote pwa mond lan. Li ofri vrè repo pou nanm ou ki bouke.", prayer: "Jezi, mwen vin jwenn ou ak tout chay mwen yo. Ban m repo ak lapè ou. Mwen depoze tout bagay nan pye ou jodi a. Amèn.", date: "" },
  { id: "11", verse: "Senyè a toupre moun ki gen kè brize, li sove moun ki gen lespri kraze.", reference: "Sòm 34:18", devotional: "Nan doulè ou ki pi fon, Bondye vin pi pre. Li pa lwen ou e li pa endiferan ak soufrans ou. Li pran swen kè ki kraze ak tandres epi li pote gerizon.", prayer: "Senyè, vin pre m nan brize m nan. Geri kè m epi restore lespri m. Mèsi pou konpasyon tandre ou. Amèn.", date: "" },
  { id: "12", verse: "Paske nou mache pa lafwa, pa pa sa nou wè.", reference: "2 Korentyen 5:7", devotional: "Lafwa vle di fè Bondye konfyans menm lè ou pa ka wè rezilta a. Se asirans konfyan ke Bondye fidèl ak pwomès li yo. Avanse ak kran nan lafwa jodi a.", prayer: "Papa, ranfòse lafwa mwen. Ede m mache pa lafwa e pa pa sa m wè, fè ou konfyans nan chak pa. Amèn.", date: "" },
  { id: "13", verse: "Pa bay kò nou traka pou anyen. Men, nan tout sikonstans, fè Bondye konnen sa nou bezwen nan lapriyè ak siplikasyon, avèk aksyon de gras.", reference: "Filipyen 4:6", devotional: "Bondye envite ou chanje enkyetid ou pou lapè li atravè lapriyè. Olye ou enkyete, pote chak pwoblèm ba li ak yon kè rekonesan. Li pran swen chak detay nan lavi ou.", prayer: "Senyè, mwen ba ou tout enkyetid ak traka mwen yo. Ranpli m ak lapè ou pandan m ap pote demann mwen yo devan ou ak rekonesans. Amèn.", date: "" },
  { id: "14", verse: "Epi lapè Bondye a ki depase tout sa lèzòm ka konprann, ap veye sou kè nou ak panse nou nan Jezikri.", reference: "Filipyen 4:7", devotional: "Lapè Bondye a sinatirèl. Li ale pi lwen pase lojik imen e li veye sou anndan ou. Lè ou konfye lavi ou a Kris, lapè li vin tounen yon fòtrès alantou kè ou.", prayer: "Papa, kite lapè ou ki depase tout konpreyansyon veye sou kè m ak panse m jodi a. Nan Jezikri, Amèn.", date: "" },
  { id: "15", verse: "Senyè a se fòs mwen ak boukliye mwen; kè m fè l konfyans, e li ede m.", reference: "Sòm 28:7", devotional: "Bondye se ni fòs ou pou vwayaj la ni boukliye ou kont danje. Lè kè ou fè l totalman konfyans, ou fè eksperyans èd li nan fason konkrep. Li pa janm manke moun ki depann sou li.", prayer: "Senyè, se fòs mwen ak boukliye m jodi a. Mwen mete tout konfyans mwen nan ou, konnen ou ap ede m. Amèn.", date: "" },
  { id: "16", verse: "Voye tout enkyetid nou sou li, paske li pran swen nou.", reference: "1 Pyè 5:7", devotional: "Bondye renmen ou anpil e li vle pote chay ou yo. Pa kenbe enkyetid lè ou ka bay li a Sila ki pran swen ou plis pase nenpòt lòt moun.", prayer: "Papa, mwen voye tout enkyetid mwen sou ou kounye a. Mèsi paske ou pran swen mwen tèlman. Amèn.", date: "" },
  { id: "17", verse: "Bondye se refij nou e fòs nou, yon sekou ki toujou la nan moman twoub.", reference: "Sòm 46:1", devotional: "Nan chak tanpèt lavi a, Bondye se kote ki an sekirite pou ou. Li pa sèlman disponib pafwa men li toujou la nan lè bezwen ou. Kouri jwenn li epi jwenn fòs ki pa ka branle.", prayer: "Senyè, ou se refij mwen ak fòs mwen. Se sekou m ki toujou la nan chak twoub m ap fè fas. Amèn.", date: "" },
  { id: "18", verse: "Nan konmansman, Bondye kreye syèl la ak tè a.", reference: "Jenèz 1:1", devotional: "Bondye ki kreye tout bagay soti nan anyen se menm Bondye ki kenbe lavi ou nan men li. Si li ka pale linivè vin egziste, li ka jere nenpòt sa ou ap fè fas jodi a.", prayer: "Bondye Kreyatè, mwen kanpe nan emèvèyman devan pouvwa ou. Menm men ki fè syèl yo kenbe lavi m. Mwen fè ou konfyans totalman. Amèn.", date: "" },
  { id: "19", verse: "Se konsa, Bondye kreye moun pòtre ak li. Li kreye yo gason e fi.", reference: "Jenèz 1:27", devotional: "Ou kreye nan imaj Bondye li menm. Sa ba ou valè, diyite ak objektif. Ou pa yon aksidan men yon chèdèv Kreyatè a te konsevwa.", prayer: "Papa, mèsi paske ou kreye m nan imaj ou. Ede m wè tèt mwen ak lòt moun atravè je lanmou ou. Amèn.", date: "" },
  { id: "20", verse: "Non Senyè a se yon fò ki solid; moun ki mache dwat kouri ladan l epi yo an sekirite.", reference: "Pwovèb 18:10", devotional: "Non Bondye li menm se yon kote pwoteksyon. Lè ou rele non li, ou ap kouri nan yon fòtrès ki pa ka pénétre. Okenn ènmi pa ka rive jwenn ou lè ou abrite nan non li.", prayer: "Senyè, mwen kouri nan non ou pou sekirite. Se fò solid mwen ak kote refij mwen jodi a. Amèn.", date: "" },
  { id: "21", verse: "Pran plezi ou nan Senyè a, epi l a ba ou sa kè ou mande.", reference: "Sòm 37:4", devotional: "Lè ou jwenn pi gwo kè kontan ou nan Bondye, li fòme dezi ou yo pou yo aliyen ak volonte pafè li. Lè ou pran plezi nan li sa transfòme sa ou vle nan sa li vle ba ou.", prayer: "Senyè, ede m pran plezi nan ou anwo tout lòt bagay. Aliyen dezi m yo ak volonte pafè ou pou lavi m. Amèn.", date: "" },
  { id: "22", verse: "Senyè a ap goumen pou nou; nou menm rete trankil.", reference: "Egzòd 14:14", devotional: "Pafwa pi gwo ak lafwa se rete trankil e kite Bondye goumen batay ou yo. Ou pa oblije lite oswa goumen. Fè konfyans ke li ap travay pou ou.", prayer: "Senyè, mwen chwazi rete trankil epi fè konfyans ke ou ap goumen pou mwen. Ban m pasyans ak lafwa nan lè pa ou. Amèn.", date: "" },
  { id: "23", verse: "Paske kote de ou twa moun reyini nan non mwen, mwen la nan mitan yo.", reference: "Matye 18:20", devotional: "Kris pwomèt prezans li chak fwa kwayan reyini nan non li. Gen pouvwa nan kominote ak lapriyè ansanm. Ou pa janm poukont ou nan vwayaj lafwa ou.", prayer: "Jezi, mèsi pou prezans ou lè nou reyini nan non ou. Beni kominyon nou an epi ini nou nan lanmou. Amèn.", date: "" },
  { id: "24", verse: "Sila ki te kòmanse yon bon travay nan nou an, l ap kontinye l jouk li fini l nan jou Kris Jezi a.", reference: "Filipyen 1:6", devotional: "Bondye poko fini ak ou. Travay li te kòmanse nan lavi ou ap fini. Chak goumen se yon pati nan pwosesis li pou fè ou vin plis tankou Kris.", prayer: "Papa, mèsi paske ou poko fini ak mwen. Konplete bon travay ou te kòmanse nan lavi m nan. Amèn.", date: "" },
  { id: "25", verse: "Men fwi Lespri a se lanmou, kè kontan, lapè, pasyans, bonte, byenveyans, fidelite, dousè, metriz.", reference: "Galat 5:22-23", devotional: "Pandan ou mache ak Sentespri a, karaktè li fleri anndan ou. Bèl kalite sa yo pa reyalize pa efò men yo grandi atravè soumisyon a Lespri Bondye.", prayer: "Sentespri, pwodui fwi ou nan lavi m. Fè lanmou, kè kontan, lapè ak tout karaktè ou grandi anndan m. Amèn.", date: "" },
  { id: "26", verse: "Okenn zam yo fòje kont ou p ap mache, e tout lang ki leve kont ou nan tribinal, w ap kondane yo.", reference: "Ezayi 54:17", devotional: "Bondye deklare ke okenn atak kont ou p ap reyisi. Pwoteksyon li kouvri ou nèt. Kanpe fèm sou pwomès sa a epi refize kite plan ènmi an branle ou.", prayer: "Senyè, mwen kanpe sou pwomès ou ke okenn zam yo fòje kont mwen p ap mache. Ou se defansè m. Amèn.", date: "" },
  { id: "27", verse: "Senyè a beni ou, li pwoteje ou. Senyè a fè fas li klere sou ou, li fè ou gras.", reference: "Nonm 6:24-25", devotional: "Benediksyon ansyen sa a se kè Bondye pou ou jodi a. Li vle beni ou, kenbe ou an sekirite, klere favè li sou ou epi vide gras li. Resevwa benediksyon li ak bra louvri.", prayer: "Senyè, mwen resevwa benediksyon ou jodi a. Kite figi ou klere sou mwen epi fè m gras. Amèn.", date: "" },
  { id: "28", verse: "Si Bondye pou nou, ki moun ki ka kont nou?", reference: "Women 8:31", devotional: "Lè Bondye Toupisan an sou bò ou, okenn opozisyon pa ka finalman genyen. Sa se pa yon panse dezirye men yon verite ki pisan. Bondye linivè a pou ou.", prayer: "Papa, mèsi paske ou pou mwen. Ak ou sou bò m, mwen pa gen anyen pou m pè. Ranfòse konfyans mwen nan ou. Amèn.", date: "" },
  { id: "29", verse: "Mwen di nou sa pou nou ka gen lapè nan mwen. Nan mond lan n ap gen tribilasyon. Men, pran kouraj! Mwen gen laviktwa sou mond lan.", reference: "Jan 16:33", devotional: "Jezi onèt sou reyalite twoub, men li deklare tou viktwa total. Lapè li disponib pou ou nan mitan nenpòt tanpèt paske li deja genyen.", prayer: "Jezi, mèsi paske ou gen laviktwa sou mond lan. Ban m lapè ou nan chak twoub m fè fas. Mwen pran kouraj paske ou genyen. Amèn.", date: "" },
  { id: "30", verse: "Pawòl ou se yon lanp pou pye m, se yon limyè sou chemen m.", reference: "Sòm 119:105", devotional: "Pawòl Bondye klere pwochen pa ou. Ou ka pa wè tout vwayaj la, men verite li bay ou ase limyè pou jodi a. Kite Bib la gide desizyon ou ak direksyon ou.", prayer: "Senyè, kite Pawòl ou klere chemen m jodi a. Gide pa m atravè verite ak sajès ou. Amèn.", date: "" },
  { id: "31", verse: "Paske se gras Bondye ki sove nou, pa mwayen lafwa. Sa pa soti nan nou menm, se kado Bondye a.", reference: "Efezyen 2:8", devotional: "Delivrans se yon kado gratis Bondye, pa yon bagay ou ka merite. Gras li rive jwenn ou lè ou pa t ka rive jwenn li. Resevwa kado sa a ak yon kè rekonesan.", prayer: "Papa, mèsi pou kado delivrans pa gras atravè lafwa. Ede m viv nan rekonesans pou kado etonan ou a. Amèn.", date: "" },
  { id: "32", verse: "Rete trankil epi konnen ke se mwen ki Bondye. M ap leve pami nasyon yo, m ap leve sou tè a.", reference: "Sòm 46:10", devotional: "Nan yon mond ki gen bri ak aktivite, Bondye rele ou nan silans. Nan kote trankil sa a, ou dekouvri ki moun li ye vrèman. Fè yon poz, respire, epi konnen ke li se Bondye sou tout bagay.", prayer: "Senyè, ede m rete trankil devan ou. Nan silans la, revele tèt ou ban mwen. Ou se Bondye epi mwen fè ou konfyans. Amèn.", date: "" },
  { id: "33", verse: "Si yon moun nan Kris, li vin yon nouvo kreyati. Ansyen bagay yo pase, gade, tout bagay vin tounèf!", reference: "2 Korentyen 5:17", devotional: "Nan Kris, ou vin tounèf nèt. Pase ou pa defini ou. Bondye ba ou yon nouvo kòmansman ak yon nouvo idantite. Mache nan libète ki moun ou ye nan li.", prayer: "Senyè Jezi, mèsi paske ou fè m yon nouvo kreyati. Ede m kite ansyen bagay yo dèyè e mache nan nouvote lavi. Amèn.", date: "" },
  { id: "34", verse: "Zèb la cheche, flè a tonbe, men pawòl Bondye nou an kanpe pou tout tan.", reference: "Ezayi 40:8", devotional: "Tout bagay nan mond sa a tanporè, men Pawòl Bondye kanpe etènèlman. Bati lavi ou sou verite li ki pa chanje e ou p ap janm branle.", prayer: "Senyè, ede m ankre lavi m nan Pawòl etènèl ou. Lè tout lòt bagay disparèt, verite ou rete pou tout tan. Amèn.", date: "" },
  { id: "35", verse: "Lanmou gen pasyans, lanmou gen bon kè. Li pa jalou, li pa fè grandizè, li pa awogan.", reference: "1 Korentyen 13:4", devotional: "Vrè lanmou, jan Bondye defini li, se dezenterese e dirab. Li reflete pwòp karaktè Bondye anvè nou. Mande li pou grandi kalite lanmou sa a nan kè ou jodi a.", prayer: "Papa, anseye m renmen jan ou renmen. Fè m gen pasyans, bon kè ak imilite nan tout relasyon m yo. Amèn.", date: "" },
  { id: "36", verse: "Kreye yon kè ki pwòp nan mwen, O Bondye, e mete yon lespri ki fèm nan mwen.", reference: "Sòm 51:10", devotional: "Bondye nan biznis renouvèlman. Li ka pran yon kè ki fatige e tache epi fè li pwòp ankò. Vin jwenn li onètman e kite li restore lavi enteryè ou.", prayer: "Bondye, kreye yon kè ki pwòp nan mwen. Renouvle yon bon lespri nan mwen. Lave m epi fè m tounèf. Amèn.", date: "" },
  { id: "37", verse: "Paske salè peche se lanmò, men kado Bondye se lavi ki p ap janm fini an nan Jezikri Senyè nou.", reference: "Women 6:23", devotional: "Peche mennen nan lanmò, men Bondye ofri lavi kòm yon kado gratis. Atravè Jezikri, pinisyon an te peye e lavi etènèl se pa ou. Sa se bon nouvèl levanjil la.", prayer: "Senyè, mèsi pou kado lavi etènèl atravè Jezi. Ede m pataje bon nouvèl sa a ak tout moun mwen rankontre. Amèn.", date: "" },
  { id: "38", verse: "Men, chache wayòm Bondye ak jistis li anvan, epi tout lòt bagay sa yo va vin jwenn nou tou.", reference: "Matye 6:33", devotional: "Lè ou mete wayòm Bondye an premye anwo tout bagay, li pran swen tout bezwen ou yo. Mete li an premye epi gade kijan li bay nan fason ou pa t janm imajine.", prayer: "Papa, ede m chache wayòm ou an premye nan tout bagay. Mwen fè ou konfyans pou bay pou tout bezwen m yo. Amèn.", date: "" },
  { id: "39", verse: "Senyè a gen bon kè e li gen pitye, li pa fè kòlè vit, li gen anpil lanmou.", reference: "Sòm 145:8", devotional: "Karaktè Bondye ranpli ak gras ak konpasyon. Li gen pasyans ak echèk ou yo e li jenerè ak lanmou li. Repoze nan konnen ke kè li anvè ou toujou bon.", prayer: "Senyè, mèsi pou gras ak konpasyon ou. Ede m reflete pasyans ak lanmou ou a lòt moun. Amèn.", date: "" },
  { id: "40", verse: "Se mwen ki chemen an, verite a ak lavi a. Pèsonn pa ka vin jwenn Papa a si li pa pase nan mwen.", reference: "Jan 14:6", devotional: "Jezi se sèl chemen ki mennen bò kote Bondye Papa a. Nan yon mond ki gen anpil vwa ak filozofi, deklarasyon li kanpe fèm. Li pa youn pami anpil chemen men sèl chemen an.", prayer: "Jezi, ou se Chemen an, Verite a ak Lavi a. Ede m swiv ou fidèlman chak jou. Amèn.", date: "" },
  { id: "41", verse: "Nan kè yon moun li fè plan, men se Senyè a ki dirije pa li yo.", reference: "Pwovèb 16:9", devotional: "Byenke li saj pou fè plan, finalman Bondye dirije chemen ou. Soumèt plan ou ba li epi fè konfyans ke direksyon li toujou pi bon pase pa ou.", prayer: "Senyè, mwen soumèt plan m yo ba ou. Etabli pa m yo dapre volonte pafè ou. Amèn.", date: "" },
  { id: "42", verse: "Senyè a, Bondye ou la, nan mitan ou, li se yon gèrye ki pisan ki ka sove. L ap pran plezi nan ou ak kè kontan, l ap kalme ou ak lanmou li.", reference: "Sofoni 3:17", devotional: "Bondye pa sèlman pisan pou sove men li pran plezi nan ou tou ak chante. Imajine Kreyatè linivè a ap pran plezi nan ou. Lanmou li pèsonèl, pisan ak dous.", prayer: "Papa, mèsi paske ou pran plezi nan mwen ak kè kontan. Kite m santi lanmou ou ap kalme nanm mwen jodi a. Amèn.", date: "" },
  { id: "43", verse: "Anwo tout bagay, youn renmen lòt anpil, paske lanmou kouvri yon pakèt peche.", reference: "1 Pyè 4:8", devotional: "Lanmou pwofon ak otantik gen pouvwa pou geri e restore relasyon. Lè nou renmen jan Kris renmen nou, nou bay gras ak padon ki kouvri ofans. Kite lanmou gide aksyon ou.", prayer: "Senyè, ede m renmen lòt moun anpil e sensèman. Kite lanmou m reflete gras ak padon ou. Amèn.", date: "" },
  { id: "44", verse: "Pa bay tèt nou traka pou denmen, paske denmen ap pote traka pa li. Chak jou gen ase tèt chaje pa li.", reference: "Matye 6:34", devotional: "Jezi anseye nou viv yon jou ala fwa. Enkyetid pou demen ka vòlè lapè jodi a. Konsantre sou sa Bondye mete devan ou jodi a epi fè li konfyans ak demen.", prayer: "Senyè, libere m anba enkyetid pou demen. Ede m viv totalman nan jodi a, fè ou konfyans ak lavni. Amèn.", date: "" },
  { id: "45", verse: "Ala bon sa bon pou moun ki mete konfyans yo nan Senyè a, ki mete espwa yo nan li.", reference: "Jeremi 17:7", devotional: "Gen yon benediksyon espesyal pou moun ki mete konfyans yo nan Bondye. Lè konfyans ou repoze nan li olye nan sikonstans, ou jwenn lapè ki pa ka branle.", prayer: "Papa, mwen mete konfyans ak espwa m nan ou sèlman. Beni m pandan m ap konte sou fidelite ou. Amèn.", date: "" },
  { id: "46", verse: "Senyè a se wòch mwen, fòtrès mwen e delivrè mwen. Bondye mwen se wòch mwen, nan li mwen jwenn refij.", reference: "Sòm 18:2", devotional: "Bondye se fondasyon solid ou lè tout lòt bagay ap tranble. Li se fòtrès ou kont ènmi an ak delivrè ou nan chak pyèj. Ou an sekirite nan li.", prayer: "Senyè, ou se wòch mwen ak fòtrès mwen. Mwen jwenn refij nan ou. Delivre m nan tout twoub epi kenbe m an sekirite. Amèn.", date: "" },
  { id: "47", verse: "M ap montre ou, m ap anseye ou chemen pou ou pran. M ap konseye ou, je m ap veye sou ou.", reference: "Sòm 32:8", devotional: "Bondye pwomèt gidaj pèsonèl ak konsèy. Li veye sou ou ak atansyon lanmou e li dirije chemen ou. Ou pa oblije rezoud lavi poukont ou.", prayer: "Senyè, montre m epi anseye m chemen pou m pran. Gide m ak konsèy lanmou ou jodi a. Amèn.", date: "" },
  { id: "48", verse: "Bondye mwen an ap satisfè tout bezwen nou selon richès glwa li nan Jezikri.", reference: "Filipyen 4:19", devotional: "Pwovizyon Bondye pa limite pa resous latè. Li bay soti nan richès glwa li, ki enfini. Fè konfyans ke li ap satisfè chak bezwen nan lavi ou.", prayer: "Papa, mwen fè ou konfyans pou satisfè tout bezwen m yo selon richès glorye ou nan Jezikri. Amèn.", date: "" },
  { id: "49", verse: "Remèt chemen ou nan men Senyè a, fè li konfyans epi l a aji. L ap fè jistis ou briye tankou limyè.", reference: "Sòm 37:5-6", devotional: "Lè ou remèt plan ak rèv ou bay Bondye, li travay pou ou. Fidelite ou ap rekonpanse. Fè konfyans nan pwosesis la epi kite Bondye pote rekonpans ou nan lè li.", prayer: "Senyè, mwen remèt chemen m nan men ou. Mwen fè ou konfyans pou reyalize objektif ou nan lavi m. Amèn.", date: "" },
  { id: "50", verse: "Geri m, Senyè, e m ap geri. Sove m, e m ap sove, paske se ou mwen fè lwanj.", reference: "Jeremi 17:14", devotional: "Bondye se gerisonè final kò, lespri ak nanm. Lè li geri, gerizon an konplè e dirab. Pote blesi ou ba li epi fè konfyans nan pouvwa restorasyon li.", prayer: "Senyè, geri m epi m ap vrèman geri. Sove m epi m ap sove. Ou sèl ki merite lwanj mwen. Amèn.", date: "" },
  { id: "51", verse: "Paske Lespri Bondye ban nou an pa fè nou kapon, men li ban nou fòs, lanmou ak kontwòl tèt nou.", reference: "2 Timote 1:7", devotional: "Bondye pa ba ou yon lespri laperèz. Lespri li anndan ou se youn ki gen pouvwa, lanmou ak bon sans. Mache ak kran nan konfyans ke Lespri li ba ou pouvwa.", prayer: "Papa, mèsi paske ou ban m yon lespri fòs, lanmou ak kontwòl tèt mwen. Chase tout laperèz nan kè m. Amèn.", date: "" },
  { id: "52", verse: "Finalman, vin fò nan Senyè a ak nan gran pouvwa li.", reference: "Efezyen 6:10", devotional: "Fòs ou pou batay espirityèl soti nan Senyè a. Gran pouvwa li disponib pou ou atravè lafwa. Kanpe fèm epi ranfòse pa resous san limit li yo.", prayer: "Senyè, mwen chwazi vin fò nan ou ak nan gran pouvwa ou. Ekipe m pou chak defi ki devan m. Amèn.", date: "" },
  { id: "53", verse: "Tann Senyè a; pran kouraj epi kite kè ou vin fò. Wi, tann Senyè a.", reference: "Sòm 27:14", devotional: "Tann Bondye mande ni fòs ni kouraj. Se pa yon bagay pasif men yon konfyans aktif nan lè pafè li. Pran kouraj, kite kè ou fò, epi konnen li ap vini.", prayer: "Senyè, ban m fòs pou tann sou ou. Ranpli kè m ak kouraj pandan m fè konfyans nan lè ou. Amèn.", date: "" },
  { id: "54", verse: "Tout bon kado ak tout kado pafè soti anwo, li desann nan men Papa limyè yo ki pa chanje tankou lonbraj k ap deplase.", reference: "Jak 1:17", devotional: "Chak benediksyon nan lavi ou soti nan men jenerè Bondye. Li pa chanje e li totalman bon. Kado li yo pafè e karaktè li konstan.", prayer: "Papa limyè yo, mèsi pou chak bon kado nan lavi m. Ou pa janm chanje e bonte ou konstan. Amèn.", date: "" },
  { id: "55", verse: "Se pou Bondye espwa a ranpli nou ak tout kè kontan ak lapè pandan n ap kwè nan li, pou nou ka debòde ak espwa pa pouvwa Sentespri a.", reference: "Women 15:13", devotional: "Bondye se sous tout espwa. Pandan ou fè li konfyans, li ranpli ou ak kè kontan ak lapè sinatirèl. Lespri li fè espwa debòde nan lavi ou pou rive nan lavi lòt moun.", prayer: "Bondye espwa a, ranpli m ak kè kontan ak lapè. Kite espwa debòde nan lavi m pa pouvwa Sentespri ou. Amèn.", date: "" },
  { id: "56", verse: "Men ou menm, Senyè, ou se yon boukliye bò kote m, glwa mwen ak sila ki leve tèt mwen wo.", reference: "Sòm 3:3", devotional: "Lè wont ak echèk eseye peze ou, Bondye leve tèt ou. Li antoure ou tankou yon boukliye e li restore diyite ou. Nan li, ou ka kenbe tèt ou wo.", prayer: "Senyè, se boukliye m jodi a. Leve tèt mwen anwo dekourajman ak wont. Ou se glwa m ak defansè m. Amèn.", date: "" },
  { id: "57", verse: "Lanmou Senyè a pa janm sispann; mizèrikòd li pa janm fini. Yo renouvle chak maten; fidelite ou gran.", reference: "Lamantasyon 3:22-23", devotional: "Chak nouvo jou pote nouvo mizèrikòd Bondye. Lanmou li pa chanjab e fidelite li gran. Pa gen enpòtans sa yè te genyen, jodi a ranpli ak nouvo gras.", prayer: "Senyè, mèsi pou mizèrikòd ou ki renouvle chak maten. Fidelite ou gran anvè mwen. Amèn.", date: "" },
  { id: "58", verse: "M ap kite lapè avèk nou, m ap ban nou lapè mwen. Mwen pa ban nou li jan mond lan bay li. Pa kite kè nou twouble e pa pè.", reference: "Jan 14:27", devotional: "Lapè Jezi ofri a pa tankou anyen mond lan ka bay. Li pwofon, dirab e disponib nan chak sikonstans. Resevwa kado lapè li epi kite laperèz ale.", prayer: "Jezi, mwen resevwa lapè ou jodi a. Kalme kè m ki twouble epi retire tout laperèz. Lapè ou se lank mwen. Amèn.", date: "" },
  { id: "59", verse: "Se mwen ki Senyè a, Bondye tout moun sou tè a. Gen yon bagay ki twò difisil pou mwen?", reference: "Jeremi 32:27", devotional: "Pa gen anyen ki twò difisil pou Bondye. Nenpòt sa ou ap fè fas, li gen pouvwa e kapasite pou jere li. Mete konfyans ou nan Sila ki pa gen limit.", prayer: "Senyè, mwen konnen pa gen anyen ki twò difisil pou ou. Mwen fè ou konfyans ak sitiyasyon ki parèt enposib nan lavi m. Amèn.", date: "" },
  { id: "60", verse: "Gade, m ap fè yon bagay nouvo! Kounye a l ap parèt. Èske nou pa wè li? M ap fè yon chemen nan dezè a ak rivyè nan savann nan.", reference: "Ezayi 43:19", devotional: "Bondye toujou ap fè nouvo bagay nan lavi ou. Menm lè tout bagay parèt sèk e esteril, li ap fè yon chemen. Louvri je ou pou wè sa l ap fè epi fè konfyans ke nouvo kòmansman ap devan ou.", prayer: "Senyè, mwen fè ou konfyans pou fè yon bagay nouvo nan lavi m. Fè yon chemen kote ki parèt pa gen chemen. Amèn.", date: "" },
  { id: "61", verse: "Mwen te chache Senyè a e li te reponn mwen; li te delivre m nan tout sa m te pè.", reference: "Sòm 34:4", devotional: "Lè ou chache Bondye ak tout kè ou, li reponn. Li pa sèlman tande ou men li aji pou delivre ou nan laperèz ou yo. Kouri jwenn li nan tout sikonstans.", prayer: "Senyè, mwen chache ou ak tout kè m. Delivre m nan tout laperèz mwen yo e reponn mwen. Amèn.", date: "" },
  { id: "62", verse: "Tout Ekriti se Bondye ki enspire li. Li itil pou anseye, pou reprimande, pou korije e pou fòme nan jistis.", reference: "2 Timote 3:16", devotional: "Bib la se pawòl Bondye ki vivan e ki enspire. Li la pou gide ou, korije ou e fòme ou nan sa ki dwat. Fè li yon pati esansyèl nan lavi chak jou ou.", prayer: "Papa, mèsi pou Pawòl enspire ou. Kite li anseye m, korije m e fòme m nan jistis chak jou. Amèn.", date: "" },
  { id: "63", verse: "Men mwen menm, mwen fè chante pou fòs ou. Chak maten m ap chante pou lanmou ou, paske ou se refij mwen, kote m kouri nan jou twoub mwen.", reference: "Sòm 59:16", devotional: "Kòmanse chak jou ak lwanj pou Bondye. Rekonèt fòs li ak lanmou li ki se refij ou. Nan moman difisil, sonje li se kote ou kouri pou jwenn pwoteksyon.", prayer: "Senyè, mwen chante pou fòs ou chak maten. Ou se refij mwen nan jou twoub. Mèsi pou lanmou konstan ou. Amèn.", date: "" },
  { id: "64", verse: "Pa imitye moun k ap viv jan mond lan viv. Kite Bondye chanje lavi ou nèt lè li chanje tout fason ou panse.", reference: "Women 12:2", devotional: "Bondye rele ou pou viv diferan de mond lan. Lè ou kite li transfòme fason ou panse, ou ka rekonèt volonte li ki bon, ki agreyab e ki pafè.", prayer: "Senyè, transfòme lavi m lè ou chanje fason m panse. Ede m pa konfòme ak mond lan men viv pou ou. Amèn.", date: "" },
  { id: "65", verse: "Senyè a bon ak tout moun; li gen pitye pou tout sa li kreye.", reference: "Sòm 145:9", devotional: "Bonte Bondye se pa sèlman pou kèk moun, men pou tout moun. Konpasyon li kouvri tout sa li fè. Kite bonte li enspire ou pou trete lòt moun ak menm jantiyès.", prayer: "Senyè, mèsi pou bonte ou ak konpasyon ou sou tout moun. Ede m reflète bonte ou a tout moun m rankontre. Amèn.", date: "" },
  { id: "66", verse: "Mwen ekri bagay sa yo pou nou menm ki kwè nan non Pitit Bondye a, pou nou ka konnen nou gen lavi ki p ap janm fini an.", reference: "1 Jan 5:13", devotional: "Ou ka gen asirans nan delivrans ou. Bondye vle ou konnen, pa sèlman espere, ke ou gen lavi etènèl. Lafwa nan Jezikri bay sètitid ak lapè.", prayer: "Papa, mèsi pou asirans ke mwen gen lavi etènèl nan Pitit ou a. Ranfòse konfyans mwen nan pwomès sa a. Amèn.", date: "" },
  { id: "67", verse: "Senyè a se gadò mwen; li ap pwoteje m kont tout danje. Li ap veye sou lavi m.", reference: "Sòm 121:7", devotional: "Bondye veye sou ou san rete. Pwoteksyon li kouvri tout aspè nan lavi ou. Ou ka dòmi an pè konnen li ap veye sou ou.", prayer: "Senyè, mèsi paske ou veye sou lavi m. Pwoteje m kont tout danje epi kenbe m an sekirite. Amèn.", date: "" },
  { id: "68", verse: "Pa pè, paske mwen avèk ou. Pa gade adwat agoch ak enkyetid, paske mwen se Bondye ou. M ap ba ou fòs, m ap ede ou.", reference: "Ezayi 41:10", devotional: "Bondye li menm di ou pa pè paske li avèk ou. Li pa sèlman gade ou de lwen, li la ak ou epi li ap ba ou fòs ak èd. Ou pa janm poukont ou.", prayer: "Bondye, mwen tande pawòl ou: pa pè. Ou avèk mwen, ou se Bondye m. Ban m fòs epi ede m jodi a. Amèn.", date: "" },
  { id: "69", verse: "Mwen kite yon egzanp pou nou, pou nou fè menm jan ak mwen.", reference: "Jan 13:15", devotional: "Jezi montre nou kijan pou viv pa egzanp li. Li anseye nou imilite, sèvis ak lanmou atravè aksyon li. Swiv egzanp li nan tout sa ou fè.", prayer: "Jezi, ede m swiv egzanp ou nan imilite ak sèvis. Kite lavi m reflete karaktè ou. Amèn.", date: "" },
  { id: "70", verse: "Tout sa ki gen souf, fè lwanj Senyè a! Lwanj Senyè a!", reference: "Sòm 150:6", devotional: "Chak souf ou pran se yon opòtinite pou fè lwanj Bondye. Li merite tout lwanj ou nan chak sikonstans lavi a. Kite lavi ou tout antye se yon chante lwanj pou li.", prayer: "Senyè, ak chak souf mwen pran, mwen fè lwanj ou. Ou merite tout lwanj mwen. Kite lavi m glorifye ou. Amèn.", date: "" },
  { id: "71", verse: "Menm si m ta mache nan fon nwa lanmò a, mwen p ap pè okenn malè, paske ou avèk mwen. Baton ou ak gòl ou se yo ki ban m kouraj.", reference: "Sòm 23:4", devotional: "Menm nan moman ki pi nwa nan lavi a, ou pa poukont ou. Prezans Bondye akonpanye ou nan chak vale. Baton li ak gòl li la pou gide ou e pwoteje ou.", prayer: "Senyè, menm nan fon nwa a, mwen pa pè paske ou avèk mwen. Baton ou ak gòl ou ban m kouraj. Amèn.", date: "" },
  { id: "72", verse: "Moun ki mete konfyans yo nan Senyè a, yo tankou mòn Siyon ki pa ka branle, ki la pou tout tan.", reference: "Sòm 125:1", devotional: "Konfyans nan Bondye ba ou yon fondasyon ki pa ka branle. Tankou yon gwo mòn ki kanpe fèm, ou p ap deplase lè ou chita sou Senyè a.", prayer: "Senyè, mwen mete konfyans mwen nan ou. Fè m tankou mòn Siyon ki pa ka branle, ki la pou tout tan. Amèn.", date: "" },
  { id: "73", verse: "Bon, sèvitè fidèl! Ou te fidèl nan ti bagay, m ap mete ou responsab anpil bagay. Antre nan kè kontan mèt ou a.", reference: "Matye 25:21", devotional: "Bondye rekonpanse fidelite, menm nan ti bagay yo. Lè ou fidèl nan sa li ba ou, li fè ou konfyans ak plis. Aplike ou pou se sèvitè fidèl nan tout sa ou fè.", prayer: "Senyè, ede m vin fidèl nan ti bagay yo. Mwen vle tande ou di: Bon, sèvitè fidèl! Amèn.", date: "" },
  { id: "74", verse: "Si nou konfese peche nou yo, li fidèl e li jis pou padone peche nou yo e pirifye nou de tout enjistis.", reference: "1 Jan 1:9", devotional: "Bondye toujou pare pou padone. Lè ou vin devan li ak imilite e konfese peche ou, li fidèl pou netwaye ou e restore ou. Pa gen peche ki twò gwo pou gras li.", prayer: "Papa, mwen konfese peche m yo devan ou. Mèsi pou fidelite ou nan padone m epi pirifye m de tout enjistis. Amèn.", date: "" },
  { id: "75", verse: "Se Senyè a ki mache devan ou. Li menm ap avèk ou, li p ap kite ou, li p ap lage ou. Pa pè, pa dekouraje.", reference: "Detewonòm 31:8", devotional: "Bondye mache devan ou pou prepare chemen an. Li dèyè ou pou pwoteje ou. Li pa janm kite ou ni lage ou. Ou pa gen rezon pou pè ni dekouraje.", prayer: "Senyè, mèsi paske ou mache devan m. Ou p ap janm kite m ni lage m. Mwen pa pè paske ou la. Amèn.", date: "" },
  { id: "76", verse: "Bondye fè tout bagay bèl nan lè li.", reference: "Eklezyas 3:11", devotional: "Bondye gen yon lè pafè pou tout bagay. Menm lè ou pa konprann poukisa bagay yo ap pran tan, fè konfyans ke li ap fè tout bagay bèl nan bon lè a.", prayer: "Senyè, ede m fè konfyans nan lè pafè ou. Ou fè tout bagay bèl nan moman ki bon an. Amèn.", date: "" },
  { id: "77", verse: "Se pou nou soumèt bay Bondye. Reziste dyab la, e l ap kouri kite nou.", reference: "Jak 4:7", devotional: "Lè ou soumèt bay Bondye premye, ou gen otorite pou reziste ènmi an. Dyab la pa ka rete kote yon moun ki soumèt bay Bondye e ki kanpe fèm nan lafwa.", prayer: "Papa, mwen soumèt bay ou jodi a. Ban m fòs pou reziste ènmi an. Nan non Jezi, li oblije kouri kite m. Amèn.", date: "" },
  { id: "78", verse: "Pa jije lòt moun pou yo pa jije nou tou.", reference: "Matye 7:1", devotional: "Bondye rele nou pou renmen, pa jije. Lè nou jije lòt moun, nou bliye ke nou menm tou nou bezwen gras. Kite Bondye jije e konsantre sou renmen lòt moun.", prayer: "Senyè, ede m pa jije lòt moun. Ranpli m ak lanmou ak konpasyon olye jijman. Amèn.", date: "" },
  { id: "79", verse: "Mwen se pye rezen an, nou se branch yo. Moun ki rete nan mwen e mwen nan li, li pote anpil fwi, paske san mwen nou pa ka fè anyen.", reference: "Jan 15:5", devotional: "Koneksyon ou ak Kris se sa ki bay fwi nan lavi ou. San li, pa gen anyen ki ka reyisi. Rete konekte ak li atravè lapriyè ak Pawòl li.", prayer: "Jezi, mwen vle rete nan ou chak jou. San ou mwen pa ka fè anyen. Ede m rete konekte e pote anpil fwi. Amèn.", date: "" },
  { id: "80", verse: "Kè kontan Senyè a se fòs nou.", reference: "Neyemi 8:10", devotional: "Kè kontan ki soti nan Senyè a se pa yon emosyon sifas men yon fòs pwofon ki soutni ou nan tout sikonstans. Jwenn kè kontan ou nan li e ou ap jwenn fòs pou chak jou.", prayer: "Senyè, ranpli m ak kè kontan ou ki se fòs mwen. Kite kè kontan sa a soutni m nan tout sikonstans. Amèn.", date: "" },
  { id: "81", verse: "Benediksyon pou moun ki gen kè pòv yo, paske wayòm syèl la se pou yo.", reference: "Matye 5:3", devotional: "Imilite espirityèl se pòt antre wayòm Bondye a. Lè ou rekonèt bezwen ou pou Bondye, ou louvri pou resevwa tout sa li gen pou bay ou.", prayer: "Senyè, ban m yon kè ki pòv devan ou. Mwen rekonèt bezwen m pou ou nan tout bagay. Amèn.", date: "" },
  { id: "82", verse: "Men Senyè a fidèl; l ap ba nou fòs e l ap pwoteje nou kont sa ki mal.", reference: "2 Tesalonisyen 3:3", devotional: "Ou ka toujou konte sou fidelite Bondye. Li ranfòse ou e pwoteje ou kont tout mal. Konfyans ou nan li pa janm mal plase.", prayer: "Senyè fidèl, mèsi paske ou ban m fòs epi ou pwoteje m kont sa ki mal. Mwen konte sou ou. Amèn.", date: "" },
  { id: "83", verse: "Chante yon chante nouvo pou Senyè a, paske li fè bagay ki meveye.", reference: "Sòm 98:1", devotional: "Chak jou pote nouvo rezon pou fè lwanj Bondye. Li ap fè bagay ki meveye nan lavi ou, menm sa ou pa ka wè kounye a. Leve yon chante nouvo pou li.", prayer: "Senyè, mwen chante yon chante nouvo pou ou paske ou fè bagay ki meveye nan lavi m. Amèn.", date: "" },
  { id: "84", verse: "Mwen plante, Apolòs te wouze, men se Bondye ki fè l grandi.", reference: "1 Korentyen 3:6", devotional: "Nou fè travay nou, men se Bondye ki bay kwasans lan. Pa dekouraje lè ou pa wè rezilta touswit. Bondye ap travay nan sa ou pa ka wè.", prayer: "Papa, mwen fè pati m nan travay la. Mwen fè ou konfyans pou bay kwasans la nan lè pa ou. Amèn.", date: "" },
  { id: "85", verse: "Si yon moun soufri paske li kretyen, pa kite sa fè l wont. Okontrè, se pou l bay Bondye glwa nan non sa a.", reference: "1 Pyè 4:16", devotional: "Pafwa swiv Kris pote soufrans, men sa pa janm yon wont. Olye sa, se yon onè pou soufri pou non li. Bondye bay gras espesyal nan moman sa yo.", prayer: "Senyè, ban m kouraj pou soufri pou non ou san wont. Kite soufrans mwen bay ou glwa. Amèn.", date: "" },
  { id: "86", verse: "Pawòl Bondye vivan e li gen pouvwa. Li pi file pase nenpòt epe de bò.", reference: "Ebre 4:12", devotional: "Pawòl Bondye pa sèlman mo sou papye. Li vivan, li gen pouvwa e li penetre nan pwofondè nanm ou. Kite li travay nan kè ou e transfòme ou chak jou.", prayer: "Senyè, kite Pawòl vivan ou travay nan kè m. Pénétre nan pwofondè nanm mwen e transfòme mwen. Amèn.", date: "" },
  { id: "87", verse: "Nan tout chemen ou, rekonèt li, e l ap fè chemen ou yo dwat.", reference: "Pwovèb 3:6", devotional: "Lè ou rekonèt Bondye nan chak aspè nan lavi ou, li fè chemen ou dwat. Pa gen desizyon ki twò piti pou pote devan li.", prayer: "Papa, mwen rekonèt ou nan tout chemen m. Fè chemen m yo dwat selon volonte ou. Amèn.", date: "" },
  { id: "88", verse: "Pa fatige fè sa ki byen, paske nan bon moman nou va rekòlte si nou pa lage.", reference: "Galat 6:9", devotional: "Fè sa ki byen ka fatige pafwa, men pa lage. Bondye pwomèt yon rekòt pou moun ki pèsevere. Kontinye simen grenn bonte ak fidelite.", prayer: "Senyè, ban m fòs pou pa fatige fè sa ki byen. Mwen fè ou konfyans pou yon rekòt nan bon moman. Amèn.", date: "" },
  { id: "89", verse: "Se Senyè a ki bon. Li se yon refij nan jou twoub. Li konnen moun ki mete konfyans yo nan li.", reference: "Nawoum 1:7", devotional: "Bonte Bondye briye plis nan jou twoub yo. Li se kote ou kouri pou jwenn refij epi li konnen pèsonèlman tout moun ki fè li konfyans.", prayer: "Senyè, ou bon anpil. Nan jou twoub mwen yo, ou se refij mwen. Mèsi paske ou konnen mwen. Amèn.", date: "" },
  { id: "90", verse: "Pa gen moun ki gen pi gwo lanmou pase moun ki bay lavi l pou zanmi l.", reference: "Jan 15:13", devotional: "Jezi te demontre pi gwo lanmou an lè li te bay lavi li pou nou. Lanmou sa a se modèl pou tout relasyon nou. Kite lanmou sakrifisyèl sa a enspire ou.", prayer: "Jezi, mèsi paske ou te bay lavi ou pou mwen. Ede m renmen lòt moun ak menm lanmou sakrifisyèl sa a. Amèn.", date: "" },
  { id: "91", verse: "Senyè a se limyè m ak delivrans mwen. Pou ki moun mwen ta pè?", reference: "Sòm 27:1a", devotional: "Lè Bondye klere chemen ou, pa gen fènwa ki ka rete. Lè li se delivrans ou, ki moun ki ka fè ou anyen? Mache ak konfyans nan limyè li.", prayer: "Senyè, ou se limyè m ak delivrans mwen. Mwen pa pè pèsonn paske ou la avèk mwen. Amèn.", date: "" },
  { id: "92", verse: "Se Senyè a ki bay, se Senyè a ki pran. Lwanj pou non Senyè a!", reference: "Jòb 1:21", devotional: "Nan bon moman ak nan move moman, Bondye merite lwanj nou. Li souverèn sou tout sikonstans e li bon nan tout sa li fè. Fè li lwanj nan tout sezon.", prayer: "Senyè, ou bay e ou pran. Nan tout sikonstans, lwanj pou non ou. Ede m fè ou lwanj nan bon e move moman. Amèn.", date: "" },
  { id: "93", verse: "Anvan ou te fèt nan vant manman ou, mwen te konnen ou. Anvan ou te soti nan vant manman ou, mwen te mete ou apa.", reference: "Jeremi 1:5", devotional: "Bondye te konnen ou anvan mond lan te egziste. Li te gen yon plan pou ou anvan ou te fèt. Ou pa yon aksidan, ou se yon kreyasyon ki gen objektif.", prayer: "Papa, mèsi paske ou te konnen m anvan m te fèt. Ou mete m apa pou yon objektif. Ede m viv nan plan ou. Amèn.", date: "" },
  { id: "94", verse: "Mwen leve je m gade mòn yo. Kote sekou m ap soti? Sekou m soti nan Senyè a ki fè syèl la ak tè a.", reference: "Sòm 121:1-2", devotional: "Sekou ou pa soti nan fòs imen oswa resous natirèl. Li soti nan Senyè a, Kreyatè syèl la ak tè a. Leve je ou bò kote li pou tout sa ou bezwen.", prayer: "Senyè, sekou m soti nan ou ki fè syèl la ak tè a. Mwen leve je m bò kote ou jodi a. Amèn.", date: "" },
  { id: "95", verse: "Rete nan lanmou mwen. Si nou kenbe kòmandman m yo, n ap rete nan lanmou m.", reference: "Jan 15:9-10", devotional: "Jezi envite ou rete nan lanmou li. Sa vle di viv nan obeyisans ak kominikasyon konstan avèk li. Lanmou li se yon kote pou ou rete, pa sèlman yon emosyon pasaje.", prayer: "Jezi, mwen vle rete nan lanmou ou. Ede m kenbe kòmandman ou yo ak kè kontan. Amèn.", date: "" },
  { id: "96", verse: "Si Bondye ak nou, ki moun ki kont nou?", reference: "Women 8:31b", devotional: "Sipò Bondye se garanti final ou. Pa gen opozisyon ki ka genyen kont sa Bondye ap sipòte. Mache ak konfyans ke Toupisan an sou bò ou.", prayer: "Papa, mèsi ke ou avèk mwen. Pa gen ènmi ki ka genyen kont mwen lè ou sou bò m. Amèn.", date: "" },
  { id: "97", verse: "Senyè a pran plezi nan moun ki gen krentif pou li, nan moun ki mete espwa yo nan lanmou li ki p ap janm fini an.", reference: "Sòm 147:11", devotional: "Bondye pran plezi nan ou lè ou gen krentif pou li e espwa nan lanmou li. Se pa pèfòmans men relasyon ki pote kè kontan Bondye. Viv nan krentif ak espwa.", prayer: "Senyè, mwen vle fè kè ou kontan. Mwen gen krentif pou ou e mwen mete espwa m nan lanmou ou ki p ap janm fini. Amèn.", date: "" },
  { id: "98", verse: "Menm lè figi a chanje e mòn yo tonbe nan mitan lanmè a, nou p ap pè.", reference: "Sòm 46:2", devotional: "Menm nan pi gwo boulvèsman yo, lafwa nan Bondye bay nou estabilite. Li pi gwo pase nenpòt tanpèt. Pa gen anyen ki ka branle ou lè ou kanpe sou li.", prayer: "Senyè, menm lè tout bagay ap chanje, mwen p ap pè paske ou la. Ou se fondasyon m ki pa ka branle. Amèn.", date: "" },
  { id: "99", verse: "Mwen pral bay kè nou yon kè nouvo e m ap mete yon lespri nouvo nan nou.", reference: "Ezekyèl 36:26", devotional: "Bondye gen pouvwa pou chanje kè ou nèt. Li retire kè ki di epi li bay yon kè nouvo ki sensib ak Lespri li. Kite li fè travay transfòmasyon sa a nan ou.", prayer: "Papa, ban m yon kè nouvo e mete yon lespri nouvo nan mwen. Transfòme mwen pa pouvwa ou. Amèn.", date: "" },
  { id: "100", verse: "An nou pwoche bò kote Bondye ak yon kè sensè e yon lafwa ki fèm.", reference: "Ebre 10:22", devotional: "Bondye envite ou vin pi pre li. Pa ezite, vin ak yon kè sensè e yon lafwa ki fèm. Li pa rejte moun ki vin bò kote li ak imilite.", prayer: "Papa, mwen pwoche bò kote ou ak yon kè sensè. Ranfòse lafwa m pandan m ap vin pi pre ou. Amèn.", date: "" },
  { id: "101", verse: "Mwen se Alfa e Omega, kòmansman an ak fen an.", reference: "Revelasyon 21:6", devotional: "Jezi se kòmansman e fen tout bagay. Li kenbe tout istwa nan men li. Pa gen anyen ki soti nan kontwòl li. Fè li konfyans ak tout istwa lavi ou.", prayer: "Senyè Jezi, ou se Alfa e Omega. Mwen fè ou konfyans ak tout istwa lavi m, kòmansman e fen. Amèn.", date: "" },
  { id: "102", verse: "Kounye a, nou se sitwayen ak sen yo e manm fanmi Bondye.", reference: "Efezyen 2:19", devotional: "Nan Kris, ou pa yon etranje men yon manm fanmi Bondye. Ou gen yon kote, yon idantite e yon eritaj nan wayòm li. Ou se pitit Bondye.", prayer: "Papa, mèsi paske m se manm fanmi ou. Mwen gen yon kote nan kay ou e yon idantite nan ou. Amèn.", date: "" },
  { id: "103", verse: "Fè tout bagay san plenyen, san diskite.", reference: "Filipyen 2:14", devotional: "Bondye rele nou pou travay ak yon bon atitid, san plenyen ni diskisyon. Lè nou obeyisan ak kè kontan, nou briye kòm limyè nan yon mond ki fè nwa.", prayer: "Senyè, ede m fè tout bagay san plenyen. Kite atitid mwen reflete kè kontan ak obeyisans. Amèn.", date: "" },
  { id: "104", verse: "Bondye pa yon moun pou li bay manti. Li pa yon moun pou li chanje lide l. Èske li di yon bagay san li pa fè li?", reference: "Nonm 23:19", devotional: "Bondye pa janm bay manti e li pa janm chanje lide li. Pawòl li solid tankou wòch. Ou ka bati tout lavi ou sou pwomès li paske li toujou kenbe pawòl li.", prayer: "Senyè, mèsi paske ou pa janm bay manti. Pawòl ou solid e pwomès ou sèten. Mwen konte sou ou. Amèn.", date: "" },
  { id: "105", verse: "Benediksyon pou moun k ap fè lapè, paske y a rele yo pitit Bondye.", reference: "Matye 5:9", devotional: "Bondye rele nou pou se moun k ap fè lapè nan mond sa a. Lè ou chache lapè ak inite, ou reflete karaktè Papa ou ki nan syèl la.", prayer: "Papa, fè m yon moun k ap fè lapè. Ede m pote lapè nan tout kote mwen ye. Amèn.", date: "" },
  { id: "106", verse: "Tankou yon papa gen pitye pou pitit li yo, se konsa Senyè a gen pitye pou moun ki gen krentif pou li.", reference: "Sòm 103:13", devotional: "Lanmou Bondye pou ou tankou lanmou yon bon papa ki gen pitye ak tandres pou pitit li. Li konprann feblès ou e li gen konpasyon pou ou.", prayer: "Papa, mèsi pou pitye ak tandres ou anvè mwen. Ou konprann feblès mwen e ou renmen m kanmenm. Amèn.", date: "" },
  { id: "107", verse: "Tout sa nou mande nan lapriyè, si nou gen lafwa, n ap resevwa li.", reference: "Matye 21:22", devotional: "Lapriyè ak lafwa se yon konbinezon pisan. Bondye envite ou mande ak konfyans nan li. Lafwa ou pa nan pwòp kapasite ou men nan kapasite Bondye ki tande lapriyè.", prayer: "Senyè, mwen mande nan lafwa konnen ke ou tande m. Ranfòse konfyans mwen nan pouvwa lapriyè. Amèn.", date: "" },
  { id: "108", verse: "Pesonn pa ka sèvi de mèt. Paske oswa l ap rayi youn e renmen lòt la, oubyen l ap atache ak youn e meprize lòt la.", reference: "Matye 6:24", devotional: "Bondye mande tout kè nou, pa sèlman yon pati. Nou pa ka sèvi li e sèvi mond lan an menm tan. Chwazi li kòm sèl Mèt ou e tout lòt bagay ap tonbe an plas.", prayer: "Senyè, ou se sèl Mèt mwen. Ede m ba ou premye plas nan lavi m e pa sèvi de mèt. Amèn.", date: "" },
  { id: "109", verse: "Li fè m mache nan chemen jistis pou non li.", reference: "Sòm 23:3b", devotional: "Bondye gide ou nan bon chemen, pa sèlman pou byen pa ou men pou glwa non li. Lè ou swiv gidaj li, lavi ou onore li e akonpli objektif li.", prayer: "Senyè, mennen m nan chemen jistis pou non ou. Kite lavi m onore ou nan tout sa m fè. Amèn.", date: "" },
  { id: "110", verse: "Paske peche p ap domine sou nou, paske nou pa anba lalwa men anba gras.", reference: "Women 6:14", devotional: "Nan Kris, peche pa gen otorite sou ou ankò. Ou viv anba gras Bondye ki ba ou pouvwa pou viv lavi nouvo. Ou lib pou viv pou Bondye.", prayer: "Senyè, mèsi paske peche pa domine sou mwen ankò. Mwen viv anba gras ou ki ban m libète. Amèn.", date: "" },
  { id: "111", verse: "Kè m fè m konfyans nan li, epi li ede m. Kè m plen kè kontan, epi mwen fè lwanj li ak chante m.", reference: "Sòm 28:7b", devotional: "Lè kè ou fè Bondye konfyans e ou fè eksperyans èd li, sa pote kè kontan ki debòde nan lwanj. Lwanj se repons natirèl yon kè ki fè eksperyans fidèlite Bondye.", prayer: "Senyè, kè m fè ou konfyans e ou ede m. Ranpli m ak kè kontan e mwen fè lwanj ou ak tout kè m. Amèn.", date: "" },
  { id: "112", verse: "Ban m lespri nou pou m konprann, m a kenbe lalwa ou e m a obeyi li ak tout kè m.", reference: "Sòm 119:34", devotional: "Konprann Pawòl Bondye mande Lespri li. Lè li louvri je ou pou wè verite nan Bib la, sa pote obeyisans ki soti nan kè, pa sèlman obligasyon.", prayer: "Senyè, ban m lespri pou konprann Pawòl ou. Ede m obeyi li ak tout kè m, pa sèlman pa devwa. Amèn.", date: "" },
  { id: "113", verse: "Moun ki gen konfyans nan richès li ap tonbe, men moun ki jis ap fleri tankou yon fèy vèt.", reference: "Pwovèb 11:28", devotional: "Richès materyèl pa ka bay sekirite vrè. Men moun ki viv nan jistis Bondye ap fleri tankou yon pyebwa ki gen rasin pwofon. Mete konfyans ou nan Bondye, pa nan lajan.", prayer: "Papa, ede m pa mete konfyans mwen nan richès men nan ou sèl. Fè m fleri nan jistis tankou yon fèy vèt. Amèn.", date: "" },
  { id: "114", verse: "Nou menm, nou se limyè mond lan. Yon vil ki chita sou tèt yon mòn pa ka kache.", reference: "Matye 5:14", devotional: "Bondye mete ou nan mond lan pou klere limyè li. Ou pa la pou kache men pou briye. Kite lavi ou se yon temwayaj ki klere pou tout moun wè.", prayer: "Senyè, ede m briye kòm limyè nan mond lan. Pa kite m kache men klere pou tout moun wè ou. Amèn.", date: "" },
  { id: "115", verse: "Paske kote trezò ou ye, se la kè ou ye tou.", reference: "Matye 6:21", devotional: "Sa ou envesti nan li revele sa ki vrèman enpòtan pou ou. Lè trezò ou nan bagay etènèl, kè ou ap suiv. Envesti nan wayòm Bondye e kè ou ap la tou.", prayer: "Senyè, ede m mete trezò m nan bagay etènèl. Aliyen kè m ak sa ki enpòtan nan je ou. Amèn.", date: "" },
  { id: "116", verse: "Men lacharite ak padon pou preyokipasyon m, fè mwen konnen jan kè ou kontan!", reference: "Sòm 51:8", devotional: "Lè Bondye padone ou, li pote kè kontan ak lapè. Li pa bay kondanasyon men konsòl e kè kontan. Kite padon li ranpli ou ak kè kontan profon.", prayer: "Papa, fè m tande kè kontan ak lajwa apre padon ou. Restore kè kontan delivrans ou ban mwen. Amèn.", date: "" },
  { id: "117", verse: "Men yon sèl bagay m ap fè: mwen bliye sa ki dèyè epi m ap eseye atenn sa ki devan m.", reference: "Filipyen 3:13", devotional: "Pa kite pase a anpeche ou avanse. Bondye gen bagay nouvo devan ou. Bliye sa ki dèyè e avanse ak detèminasyon anvè sa li gen pou ou.", prayer: "Senyè, ede m bliye sa ki dèyè e avanse ak detèminasyon. Mwen gade devan kote ou ap mennen m. Amèn.", date: "" },
  { id: "118", verse: "Mwen kite lapè pou nou. Mwen ban nou lapè mwen. Mwen pa ban nou li jan mond lan bay li.", reference: "Jan 14:27a", devotional: "Lapè Kris bay la diferan de tout sa mond lan ka ofri. Li pa depann de sikonstans men de relasyon ou avèk li. Resevwa lapè sa a ki depase konpreyansyon.", prayer: "Jezi, mwen resevwa lapè ou jodi a. Li diferan de sa mond lan bay. Kite li ranpli kè m nèt. Amèn.", date: "" },
  { id: "119", verse: "Kenbe sa ki byen. Evite tout fòm sa ki mal.", reference: "1 Tesalonisyen 5:21-22", devotional: "Viv yon lavi ki fè diferans ant sa ki bon ak sa ki mal. Kenbe sa ki bon ak tout fòs ou e evite tout sa ki sanble mal. Chache sajès Bondye pou fè bon chwa.", prayer: "Papa, ede m kenbe sa ki bon e evite tout fòm sa ki mal. Ban m sajès pou fè bon chwa chak jou. Amèn.", date: "" },
  { id: "120", verse: "Ou kreye tout sa ki anndan m, ou trikote m nan vant manman m.", reference: "Sòm 139:13", devotional: "Bondye li menm te fòme ou ak swen ak lanmou. Chak detay nan moun ou ye te fè ak entansyon. Ou se yon chèdèv ke Bondye te kreye ak pwòp men li.", prayer: "Papa, mèsi paske ou kreye m ak entansyon ak lanmou. Ede m wè tèt mwen jan ou wè m: bèl ak presye. Amèn.", date: "" },
  { id: "121", verse: "Mwen viv, men se pa mwen ankò, se Kris k ap viv nan mwen.", reference: "Galat 2:20", devotional: "Lavi kretyen an se plis pase swiv règ, se kite Kris viv atravè ou. Lè ou soumèt volonte ou bay li, li viv pouvwa rezirèksyon li nan ou chak jou.", prayer: "Jezi, mwen vle ke se ou k ap viv nan mwen. Ede m soumèt volonte m pou ou ka briye nan lavi m. Amèn.", date: "" },
  { id: "122", verse: "Tè a se pou Senyè a ak tout sa ki ladan l, mond lan ak tout moun ki rete sou li.", reference: "Sòm 24:1", devotional: "Tout bagay nan mond sa a se pou Bondye. Li se Mèt tout kreyasyon. Lè ou rekonèt sa, ou ka viv ak imilite ak rekonesans pou tout sa li mete nan men ou.", prayer: "Senyè, tout bagay se pou ou. Mwen se yon jeran sa ou mete nan men m. Ede m viv ak fidelite e rekonesans. Amèn.", date: "" },
  { id: "123", verse: "Senyè a pwòch tout moun ki rele li, tout moun ki rele li nan verite.", reference: "Sòm 145:18", devotional: "Bondye pa lwen ou. Li pwòch tout moun ki rele li sensèman. Lè ou priye ak kè ou, li la, li tande e li reponn.", prayer: "Senyè, mwen rele ou nan verite jodi a. Mèsi paske ou pwòch mwen e ou tande lapriyè m. Amèn.", date: "" },
  { id: "124", verse: "Se pou nou renmen youn lòt menm jan mwen renmen nou.", reference: "Jan 13:34", devotional: "Kòmandman Jezi a klè: renmen lòt moun menm jan li renmen ou. Sa se pa yon opsyon men yon nesesite nan lavi kretyen. Lanmou Kris se modèl pou tout relasyon nou.", prayer: "Jezi, anseye m renmen lòt moun menm jan ou renmen m. Kite lanmou ou koule nan mwen anvè tout moun. Amèn.", date: "" },
  { id: "125", verse: "Mwen mete pawòl ou nan kè m pou m pa peche kont ou.", reference: "Sòm 119:11", devotional: "Pawòl Bondye nan kè ou se pi bon defans kont tantasyon. Lè ou memorize e medite sou Bib la, li vin yon pwoteksyon pisan nan lavi ou.", prayer: "Senyè, ede m mete Pawòl ou nan kè m. Kite li pwoteje m kont peche e gide chak desizyon m. Amèn.", date: "" },
  { id: "126", verse: "Nou ka fè tout bagay nan Kris ki ban nou fòs la.", reference: "Filipyen 4:13a", devotional: "Pa gen limit nan sa ou ka akonpli lè ou konte sou fòs Kris. Li pa sèlman ba ou fòs fizik men fòs espirityèl pou chak sitiyasyon ou rankontre.", prayer: "Kris Jezi, mèsi pou fòs ou ki pèmèt mwen fè tout bagay. Mwen konte sou ou nan chak moman. Amèn.", date: "" },
  { id: "127", verse: "Ki moun ki ka separe nou ak lanmou Kris la? Tribilasyon, oswa twoub, oswa pèsekisyon?", reference: "Women 8:35", devotional: "Pa gen anyen ki ka separe ou ak lanmou Kris la. Ni twoub, ni soufrans, ni okenn fòs sou tè a ka koupe lyen lanmou sa a. Ou an sekirite nan li pou tout tan.", prayer: "Senyè Jezi, mèsi ke anyen pa ka separe m ak lanmou ou. Nan chak eprèv, lanmou ou kenbe m fèm. Amèn.", date: "" },
  { id: "128", verse: "Tout richès ak sajès ak konesans soti nan Bondye! Jijman li yo twò pwofon pou moun konprann! Chemen li yo twò wo pou moun ka swiv!", reference: "Women 11:33", devotional: "Sajès Bondye depase tout sa nou ka konprann. Jijman li pafè menm lè nou pa konprann yo. Fè li konfyans menm lè chemen li parèt misterye.", prayer: "Papa, mwen adore pwofondè sajès ak konesans ou. Chemen ou depase konpreyansyon m men mwen fè ou konfyans. Amèn.", date: "" },
  { id: "129", verse: "Pitit mwen, pa bliye sa m te moutre ou. Kenbe kòmandman m yo nan kè ou.", reference: "Pwovèb 3:1", devotional: "Bondye rele nou pitit li epi li ban nou enstriksyon pou byen nou. Lè nou kenbe pawòl li nan kè nou, li pwoteje nou e gide chemen nou.", prayer: "Papa, mwen kenbe kòmandman ou yo nan kè m. Ede m pa bliye sa ou moutre m. Amèn.", date: "" },
  { id: "130", verse: "Ann apwoche bò Bondye, e Bondye ap apwoche bò nou.", reference: "Jak 4:8", devotional: "Bondye fè yon pwomès senp men pwisan: si ou vin pi pre li, li ap vin pi pre ou. Premye pa a se pa ou, men li deja ap tann ou ak bra louvri.", prayer: "Papa, mwen apwoche bò kote ou jodi a. Mèsi paske ou ap vin pi pre m tou. Amèn.", date: "" },
  { id: "131", verse: "Bondye te kreye moun pòtre ak li. Li kreye yo gason e fi.", reference: "Jenèz 1:27b", devotional: "Ou kreye pòtre ak Bondye li menm. Sa vle di ou gen valè, diyite ak potansyèl ki depase sa ou ka imajine. Viv nan verite sa a jodi a.", prayer: "Bondye, mèsi ke m kreye nan imaj ou. Ede m viv nan valè ak diyite ke sa pote. Amèn.", date: "" },
  { id: "132", verse: "Konsa tou, lafwa san aksyon mouri.", reference: "Jak 2:26", devotional: "Lafwa vrè toujou pwodui aksyon. Sa ou kwè dwe parèt nan fason ou viv. Lafwa ak zèv mache ansanm pou yon lavi ki onore Bondye.", prayer: "Senyè, kite lafwa m parèt nan aksyon m yo. Pa kite lafwa m rete san fwi men fè li vivan ak aktif. Amèn.", date: "" },
  { id: "133", verse: "Mete tout konfyans ou nan Senyè a de tout kè ou.", reference: "Pwovèb 3:5a", devotional: "Bondye pa mande yon ti moso konfyans. Li mande tout kè ou. Lè ou fè li konfyans totalman, ou dekouvri li pi fidèl pase nenpòt lòt bagay.", prayer: "Senyè, mwen ba ou tout kè m nan konfyans. Pa yon mwatye, pa yon ti moso, men tout. Amèn.", date: "" },
  { id: "134", verse: "Men, ann di verite a nan lanmou, pou nou ka grandi nan tout fason nan Kris ki se tèt la.", reference: "Efezyen 4:15", devotional: "Verite san lanmou ka blese, men lanmou san verite pa vrè. Bondye rele nou pou di verite a nan lanmou, yon fason ki edifye olye detwi.", prayer: "Papa, ede m pale verite a ak lanmou. Kite pawòl mwen edifye lòt moun olye blese yo. Amèn.", date: "" },
  { id: "135", verse: "Nou konnen lanmou paske Jezi te bay lavi li pou nou.", reference: "1 Jan 3:16", devotional: "Lanmou pa sèlman yon mo men yon aksyon. Jezi te defini lanmou lè li te bay lavi li pou nou. Sa se modèl lanmou ki pi wo ki egziste.", prayer: "Jezi, mèsi paske ou te montre vrè lanmou lè ou te bay lavi ou pou mwen. Ede m renmen lòt moun konsa tou. Amèn.", date: "" },
  { id: "136", verse: "Senyè a ap goumen pou nou. Se pou nou rete trankil.", reference: "Egzòd 14:14b", devotional: "Gen batay kote Bondye mande ou sèlman rete trankil e kite li aji. Li pa bezwen èd ou nan tout batay. Pafwa pi gwo viktwa vini lè ou rete trankil.", prayer: "Senyè, mwen rete trankil pandan ou ap goumen pou mwen. Mwen fè ou konfyans ak batay sa a. Amèn.", date: "" },
  { id: "137", verse: "Veye, kanpe fèm nan lafwa, pran kouraj, vin fò.", reference: "1 Korentyen 16:13", devotional: "Bondye rele ou pou yon lavi vijilan ak fèm. Kanpe fèm nan lafwa, pa kouri lè defi vini. Ak kouraj Bondye, ou ka vin fò nan tout sikonstans.", prayer: "Senyè, ede m veye e kanpe fèm nan lafwa. Ban m kouraj e fè m vin fò nan ou. Amèn.", date: "" },
  { id: "138", verse: "Mwen pral ba ou kle wayòm syèl la.", reference: "Matye 16:19", devotional: "Jezi bay otorite espirityèl a disip li yo. Ou gen otorite nan non Jezi pou lapriyè e pou kanpe kont fòs ki mal. Konnen ki moun ou ye nan Kris.", prayer: "Jezi, mèsi pou otorite ou ban mwen. Ede m itilize li ak sajès pou avanse wayòm ou. Amèn.", date: "" },
  { id: "139", verse: "Kè kontan pou moun ki gen mizèrikòd, paske y a jwenn mizèrikòd tou.", reference: "Matye 5:7", devotional: "Lè ou montre mizèrikòd a lòt moun, ou ouvri chemen pou resevwa mizèrikòd tou. Bondye renmen kè ki gen konpasyon e li beni moun ki montre gras.", prayer: "Senyè, fè m yon moun ki gen mizèrikòd. Ede m montre gras a lòt moun jan ou montre m gras. Amèn.", date: "" },
  { id: "140", verse: "Mwen menm, mwen se limyè mond lan. Moun ki swiv mwen p ap janm mache nan fènwa.", reference: "Jan 8:12", devotional: "Lè ou swiv Jezi, ou pa janm nan fènwa. Li klere chemen ou e li gide ou nan verite. Li se limyè ki pa janm etenn nan yon mond ki fè nwa.", prayer: "Jezi, ou se limyè mond lan. Mwen swiv ou pou m pa janm mache nan fènwa. Klere chemen m jodi a. Amèn.", date: "" },
  { id: "141", verse: "Se mwen ki Senyè a, Bondye nou an. Se mwen ki fè nou soti nan peyi Lejip.", reference: "Egzòd 20:2", devotional: "Bondye ki te delivre Izrayèl se menm Bondye ki delivre ou jodi a. Li gen yon istwa ak ou, istwa delivrans ak pwoteksyon. Sonje sa li te fè pou ou.", prayer: "Senyè, mèsi pou delivrans ou nan lavi m. Tankou ou te delivre Izrayèl, ou delivre m tou. Amèn.", date: "" },
  { id: "142", verse: "An n ap kouri avèk pasyans nan kous ki devan nou an, pandan n ap gade Jezi.", reference: "Ebre 12:1-2", devotional: "Lavi kretyen se yon kous ki mande pèseverans. Konsantre je ou sou Jezi, ki te kòmanse e ki pral fini lafwa ou. Li se egzanp pafè pou kouri kous la.", prayer: "Jezi, mwen fikse je m sou ou pandan m ap kouri kous la. Ban m pasyans e pèseverans jouk lafen. Amèn.", date: "" },
  { id: "143", verse: "Lè m pè, mwen mete konfyans mwen nan ou.", reference: "Sòm 56:3", devotional: "Laperèz se yon reyalite, men lafwa se yon chwa. Menm lè ou pè, ou ka chwazi mete konfyans ou nan Bondye. Li pi gran pase tout sa ki fè ou pè.", prayer: "Papa, lè m pè, mwen chwazi mete konfyans mwen nan ou. Ou pi gran pase tout laperèz mwen. Amèn.", date: "" },
  { id: "144", verse: "Remèsye Bondye nan tout sikonstans, paske se sa Bondye vle pou nou nan Jezikri.", reference: "1 Tesalonisyen 5:18", devotional: "Rekonesans pa depann de sikonstans, se yon atitid kè. Bondye mande nou remèsye li nan tout bagay paske li konnen sa transfòme pèspektiv nou e rapwoche nou bò kote li.", prayer: "Papa, mwen remèsye ou nan tout sikonstans. Ede m gen yon kè rekonesan nan bon tanp ak move tanp. Amèn.", date: "" },
  { id: "145", verse: "Verite a ap libere nou.", reference: "Jan 8:32", devotional: "Verite Bondye a gen pouvwa pou libere ou nan tout kalite esklavaj. Lè ou konnen verite a e viv ladan l, li kase chenn ki te kenbe ou e li ba ou vrè libète.", prayer: "Senyè, kite verite ou libere m nan tout sa ki kenbe m prizonye. Mwen vle mache nan libète ou. Amèn.", date: "" },
  { id: "146", verse: "Sonje, mwen avèk nou tout tan, jouk lafen mond lan.", reference: "Matye 28:20", devotional: "Dènye pwomès Jezi a te ke li ap toujou la avèk ou. Pa gen kote ou ka ale kote li pa la. Prezans li akonpanye ou jodi a, demen e pou tout tan.", prayer: "Jezi, mèsi ke ou avèk mwen tout tan. Mwen pa janm poukont mwen. Prezans ou se pi gwo kado m. Amèn.", date: "" },
  { id: "147", verse: "Bondye ki rich nan mizèrikòd, poutèt gran lanmou li te renmen nou ak li a, menm lè nou te mouri nan peche nou yo, li fè nou vivan ansanm ak Kris.", reference: "Efezyen 2:4-5", devotional: "Mizèrikòd Bondye rich e lanmou li gran. Menm lè nou te nan eta ki pi mal, li te chwazi ban nou lavi. Se pa sa nou te merite men sa lanmou li te bay.", prayer: "Papa, mèsi pou mizèrikòd rich ou ak gran lanmou ou. Ou te fè m vivan lè m te mouri nan peche m. Amèn.", date: "" },
  { id: "148", verse: "Mwen se pòt la. Si yon moun antre pa mwen, l ap sove.", reference: "Jan 10:9", devotional: "Jezi se sèl pòt ki mennen nan delivrans ak lavi etènèl. Antre pa li e ou ap jwenn sekirite, libète ak abondans nan lavi.", prayer: "Jezi, ou se pòt la. Mwen antre pa ou e mwen jwenn delivrans. Mèsi pou sekirite ak lavi ou ban mwen. Amèn.", date: "" },
  { id: "149", verse: "Yon kè ki gen kè kontan se bon remèd, men yon lespri ki kraze seche zo.", reference: "Pwovèb 17:22", devotional: "Kè kontan gen pouvwa gerizon. Bondye vle ou gen kè kontan ki soti nan li, yon kè kontan ki bay fòs ak sante. Pa kite dekourajman kraze ou men kite kè kontan Senyè a geri ou.", prayer: "Senyè, ranpli m ak kè kontan ki se bon remèd. Chase dekourajman e ban m yon lespri ki jwa. Amèn.", date: "" },
  { id: "150", verse: "Senyè a ap pwoteje ou kont tout danje. Li ap kenbe lavi ou.", reference: "Sòm 121:7a", devotional: "Pwomès Bondye pou pwoteksyon kouvri tout aspè nan lavi ou. Li pa sèlman pwoteje kò ou men nanm ou tou. Ou ka repoze nan sekirite konplè li.", prayer: "Senyè, mwen konte sou pwoteksyon ou kont tout danje. Kenbe lavi m nan men pisan ou. Amèn.", date: "" },
  { id: "151", verse: "Fè konfyans nan Senyè a ak tout kè ou e pa konte sou entèlijans pa ou.", reference: "Pwovèb 3:5b", devotional: "Entèlijans imen gen limit, men sajès Bondye enfini. Lè ou chwazi fè li konfyans olye konte sou tèt ou, ou louvri pòt pou gidaj sinatirèl li.", prayer: "Papa, mwen pa konte sou entèlijans pa m men sou sajès ou. Gide m ak konesans enfini ou. Amèn.", date: "" },
  { id: "152", verse: "Mwen pral fè yon chemen nan dezè a e rivyè nan tè sèk la.", reference: "Ezayi 43:19b", devotional: "Bondye espesyalize nan fè chemen kote ki pa t gen chemen. Nan moman ki pi sèk nan lavi ou, li ka fè rivyè dlo koule. Pa gen sitiyasyon ki twò dezespere pou li.", prayer: "Senyè, fè yon chemen nan dezè lavi m. La kote tout bagay sèk, fè rivyè dlo koule. Amèn.", date: "" },
  { id: "153", verse: "Peche yo kouche nan papòt la, men nou dwe domine sou li.", reference: "Jenèz 4:7", devotional: "Tantasyon toujou la, men ou pa oblije tonbe ladan l. Bondye ba ou kapasite pou domine sou peche. Ak Lespri li anndan ou, ou gen pouvwa pou reziste.", prayer: "Papa, ban m fòs pou domine sou peche. Lè tantasyon frape, ede m kanpe fèm nan pouvwa Lespri ou. Amèn.", date: "" },
  { id: "154", verse: "Kòmande sòlda ki rich pou yo pa gen lògèy e pou yo pa mete espwa yo nan richès ki pa sèten.", reference: "1 Timote 6:17", devotional: "Richès materyèl pa dwe vin idòl nou. Bondye averti nou pou pa mete espwa nou nan richès ki ka disparèt. Olye sa, mete espwa ou nan Bondye ki bay tout bagay abondaman.", prayer: "Senyè, ede m pa mete espwa m nan richès men nan ou sèl ki bay tout bagay abondaman. Amèn.", date: "" },
  { id: "155", verse: "Li bay moun ki fatige fòs, e li ogmante pouvwa moun ki fèb.", reference: "Ezayi 40:29", devotional: "Lè ou rive nan bout fòs ou, Bondye kòmanse. Li bay fòs a moun ki fatige e pouvwa a moun ki fèb. Feblès ou se opòtinite pou pouvwa li.", prayer: "Senyè, ban m fòs nan fatig mwen. Nan feblès mwen, pouvwa ou parèt. Mèsi paske ou ranfòse m. Amèn.", date: "" },
  { id: "156", verse: "Se konsa, chak fwa gen yon moun ki nan Kris, li tounen yon lòt moun. Bagay lontan yo disparèt, se lòt bagay nèf ki pran plas yo.", reference: "2 Korentyen 5:17b", devotional: "Transfòmasyon nan Kris se konplè e reyèl. Ansyen bagay yo ale e nouvo a rive. Ou pa menm moun ou te ye paske Kris fè ou tounèf nèt.", prayer: "Jezi, mèsi paske m se yon kreyati nouvo nan ou. Ansyen bagay yo ale e tout bagay vin tounèf. Amèn.", date: "" },
  { id: "157", verse: "Ban m entèlijans pou m kenbe lwa ou e obeyi li ak tout kè m.", reference: "Sòm 119:34b", devotional: "Entèlijans espirityèl se yon kado Bondye bay. Li louvri lespri ou pou konprann Pawòl li pi byen e obeyi ak kè kontan olye ak obligasyon.", prayer: "Senyè, ban m entèlijans pou konprann Pawòl ou. Kite obeyisans mwen soti nan kè, pa nan obligasyon. Amèn.", date: "" },
  { id: "158", verse: "Paske Pitit Lòm nan te vini pou chache e sove sa ki te pèdi.", reference: "Lik 19:10", devotional: "Jezi te vini espesyalman pou sa ki pèdi yo. Pa gen moun ki twò lwen pou lanmou li pa ka rive jwenn yo. Li chache ou ak pasyon e li sove ou ak gras.", prayer: "Jezi, mèsi paske ou te vini chache m lè m te pèdi. Lanmou ou te rive jwenn mwen e sove mwen. Amèn.", date: "" },
  { id: "159", verse: "Mwen pa p kite nou san papa. M ap retounen vin jwenn nou.", reference: "Jan 14:18", devotional: "Jezi pa janm abandone pitit li yo. Li te pwomèt retounen e Lespri li la ak ou jodi a. Ou pa janm yon òfelen espirityèl, ou gen yon Papa ki la.", prayer: "Jezi, mèsi ke ou pa kite m san papa. Prezans ou ak mwen e ou ap retounen. Mwen pa poukont mwen. Amèn.", date: "" },
  { id: "160", verse: "Pawòl mwen p ap retounen vin jwenn mwen san li pa fè sa m vle a.", reference: "Ezayi 55:11", devotional: "Lè Bondye pale, pawòl li akonpli objektif li. Pa gen pawòl li ki tonbe atè san efè. Fè konfyans ke pwomès li ap reyalize nan lavi ou.", prayer: "Senyè, mèsi ke Pawòl ou pa retounen vid. Li akonpli tout sa ou voye li fè. Mwen konte sou pwomès ou. Amèn.", date: "" },
  { id: "161", verse: "Bondye pa gen patipri. Nan tout nasyon, moun ki gen krentif pou li e ki fè sa ki dwat, li aksepte yo.", reference: "Travay 10:34-35", devotional: "Bondye pa gen favori. Li resevwa tout moun ki vini bò kote li ak kè sensè. Pa gen ras, klas oswa nasyon ki pi presye pase lòt nan je li.", prayer: "Papa, mèsi ke ou aksepte tout moun san patipri. Ede m wè tout moun menm jan ou wè yo. Amèn.", date: "" },
  { id: "162", verse: "Si ou dakò ak bouch ou ke Jezi se Senyè a e si ou kwè nan kè ou ke Bondye te leve li vivan pami mò yo, w ap sove.", reference: "Women 10:9", devotional: "Delivrans disponib pou tout moun ki kwè ak kè yo e konfese ak bouch yo. Se pa yon bagay konplike men yon repons senp nan lafwa a lanmou Bondye.", prayer: "Senyè Jezi, mwen konfese ke ou se Senyè a. Mwen kwè Bondye te leve ou vivan pami mò yo. Mwen sove pa gras ou. Amèn.", date: "" },
  { id: "163", verse: "Li ponpe tout sa ki awogan yo, men li bay moun ki enb gras li.", reference: "Jak 4:6", devotional: "Imilite se chemen ki mennen nan gras Bondye. Lè ou desann tèt ou devan li, li leve ou. Men ògèy fèmen pòt gras la. Chwazi imilite e resevwa gras li.", prayer: "Papa, ban m yon kè ki enb. Ede m evite ògèy e mache nan imilite pou m ka resevwa gras ou. Amèn.", date: "" },
  { id: "164", verse: "Senyè a te di Moyiz: Mwen se sa m ye a.", reference: "Egzòd 3:14", devotional: "Bondye pa bezwen defini li menm pa anyen lòt bagay. Li se sa li ye. Li sifi, li pafè e li etènèl. Lè ou konnen li, ou konnen tout sa ou bezwen.", prayer: "Bondye, ou se sa ou ye. Pa gen pawòl ki ka dekri ou totalman. Mwen adore ou pou grandè ou. Amèn.", date: "" },
  { id: "165", verse: "M ap voye zanj mwen devan ou pou li pwoteje ou sou chemen ou e pou li mennen ou kote m prepare pou ou.", reference: "Egzòd 23:20", devotional: "Bondye mete pwoteksyon sinatirèl sou chemen ou. Li prepare chemen an devan ou e li voye èd pou gide ou. Ou pa mache poukont ou, Bondye ap veye sou ou.", prayer: "Papa, mèsi pou pwoteksyon ou sou chemen m. Ou prepare tout bagay devan m e ou gide pa m yo. Amèn.", date: "" },
  { id: "166", verse: "Pa bay lachte pou sa ki dwat, men kite sa ki dwat gide kè ou.", reference: "Pwovèb 4:23", devotional: "Kè ou se sous lavi. Sa ki anndan li detèmine direksyon lavi ou. Veye sou kè ou ak dilijans paske sa ou mete ladan l, se sa ki va soti.", prayer: "Senyè, ede m veye sou kè m ak dilijans. Kite sa ki dwat gide kè m nan tout sa m fè. Amèn.", date: "" },
  { id: "167", verse: "Sila ki kwè nan Pitit la gen lavi ki p ap janm fini an.", reference: "Jan 3:36", devotional: "Lafwa nan Pitit Bondye a bay yon lavi ki pa gen fen. Sa se pa sèlman yon lavi ki long men yon kalite lavi nouvo ki kòmanse kounye a e ki dire pou tout tan.", prayer: "Jezi, mwen kwè nan ou e mwen gen lavi ki p ap janm fini an. Mèsi pou kado presye sa a. Amèn.", date: "" },
  { id: "168", verse: "Lave men nou, pechè yo. Pirifye kè nou, moun ki gen de lide.", reference: "Jak 4:8b", devotional: "Bondye rele nou nan pirite ak angajman total. Li pa vle yon kè ki divize men yon kè ki dedye nèt ba li. Kite li lave ou e pirifye ou jodi a.", prayer: "Papa, lave m e pirifye kè m. Mwen pa vle gen de lide men yon kè ki dedye nèt ba ou. Amèn.", date: "" },
  { id: "169", verse: "Mwen prale prepare yon plas pou nou.", reference: "Jan 14:2", devotional: "Jezi ale prepare yon kote espesyal pou ou nan syèl. Sa vle di ou gen yon avni asire nan prezans li pou tout tan. Ou se yon envite espesyal nan kay Papa a.", prayer: "Jezi, mèsi paske ou ap prepare yon plas pou mwen. Mwen gade devan ak espwa pou jou mwen va avèk ou pou tout tan. Amèn.", date: "" },
  { id: "170", verse: "Kè kontan pou moun ki grangou e swaf pou jistis, paske y a satisfè.", reference: "Matye 5:6", devotional: "Lè ou gen yon dezi pwofon pou jistis Bondye, li pwomèt satisfè ou. Bondye pa janm kite moun ki chache li ak tout kè yo rete vid.", prayer: "Senyè, ban m grangou ak swaf pou jistis ou. Satisfè nanm mwen ak prezans ou ak verite ou. Amèn.", date: "" },
  { id: "171", verse: "Moun ki gen pasyans pi fò pase gèrye, e moun ki kontwole tèt li pi fò pase sa ki pran yon vil.", reference: "Pwovèb 16:32", devotional: "Vrè fòs se pa nan vyolans men nan kontwòl tèt ou ak pasyans. Bondye konsidere moun ki ka kenbe kalm li pi fò pase yon gèrye ki genyen yon batay.", prayer: "Papa, ban m pasyans ak kontwòl tèt mwen. Sa se vrè fòs nan je ou. Fè m vin fò pa anndan. Amèn.", date: "" },
  { id: "172", verse: "Gade ki jan zwazo nan syèl la! Yo pa simen, yo pa rekòlte, men Papa nou ki nan syèl la ba yo manje.", reference: "Matye 6:26", devotional: "Si Bondye pran swen zwazo yo, konbyen plis li pran swen ou! Pa enkyete ou pou bezwen ou yo. Papa ou nan syèl la konnen sa ou bezwen e li ap bay.", prayer: "Papa, si ou nouri zwazo yo, ou ap nouri m tou. Mwen mete konfyans mwen nan pwovizyon ou pou mwen. Amèn.", date: "" },
  { id: "173", verse: "Se pou nou gen menm santiman ki te nan Jezikri.", reference: "Filipyen 2:5", devotional: "Bondye vle ou panse tankou Jezi te panse: ak imilite, sèvis ak lanmou. Lè ou adopte mentalite Kris la, aksyon ou reflete karaktè li.", prayer: "Jezi, ban m menm santiman ou te genyen. Fòme panse m pou reflete imilite ak lanmou ou. Amèn.", date: "" },
  { id: "174", verse: "Tout moun ki travay e ki gen chay lou, vin jwenn mwen. M a ba nou repo.", reference: "Matye 11:28b", devotional: "Envitasyon Jezi a klè e ouvè: vin jwenn li ak chay ou. Li pa kritike ou pou chay la, li senpleman ofri repo. Repo li a se yon kado, pa yon bagay ou merite.", prayer: "Jezi, mwen vini ak tout chay lou m yo. Ban m repo ou ki se yon kado presye. Mèsi pou jantiyès ou. Amèn.", date: "" },
  { id: "175", verse: "M ap reponn ou anvan menm ou fini priye.", reference: "Ezayi 65:24", devotional: "Bondye konnen bezwen ou anvan menm ou mande. Li deja ap prepare repons la pou lapriyè ou. Konfyans nan li paske li pa janm an reta nan bay ou sa ou bezwen.", prayer: "Papa, mèsi ke ou deja ap reponn lapriyè m anvan m menm fini priye. Ou konnen bezwen m anvan m pale. Amèn.", date: "" },
  { id: "176", verse: "Se poutèt sa, met sou nou tout zam Bondye a pou nou ka kanpe nan jou ki mal la.", reference: "Efezyen 6:13", devotional: "Bondye ba ou tout ekipman ou bezwen pou batay espirityèl. Met sou ou zam li yo chak jou: verite, jistis, lafwa, delivrans ak Pawòl li. Ou byen ekipe.", prayer: "Senyè, ede m met sou mwen tout zam Bondye chak jou. Ekipe m pou kanpe fèm nan jou ki mal la. Amèn.", date: "" },
  { id: "177", verse: "Yon bon non pi bon pase anpil richès, e favè pi bon pase ajan ak lò.", reference: "Pwovèb 22:1", devotional: "Karaktè ou gen plis valè pase tout richès mond lan. Yon bon repitasyon ki bati sou entegrite bay yon eritaj ki dire plis pase lajan.", prayer: "Papa, ede m bati yon bon non atravè entegrite. Kite karaktè m gen plis valè pase richès materyèl. Amèn.", date: "" },
  { id: "178", verse: "Si nou peche, nou gen yon avoka bò kote Papa a: Jezikri ki jis la.", reference: "1 Jan 2:1", devotional: "Lè ou tonbe nan peche, ou gen yon avoka nan syèl la ki kanpe pou ou. Jezi pa kondane ou men li plede ka ou devan Papa a. Gras li kouvri echèk ou.", prayer: "Jezi, mèsi paske ou se avoka m bò kote Papa a. Lè m tonbe, ou kanpe pou mwen ak gras ou. Amèn.", date: "" },
  { id: "179", verse: "E se konsa mwen menm m ap fè tout mwen kapab pou gen yon konsyans ki klè devan Bondye e devan lèzòm.", reference: "Travay 24:16", devotional: "Yon konsyans ki klè se yon benediksyon presye. Travay pou kenbe relasyon ou ak Bondye e ak lòt moun san blòk. Viv ak entegrite nan tout sa ou fè.", prayer: "Senyè, ede m kenbe yon konsyans ki klè devan ou ak devan lèzòm. Kite entegrite gide lavi m. Amèn.", date: "" },
  { id: "180", verse: "Se avèk baton an fè m te dirije yo, avèk kòd lanmou.", reference: "Oze 11:4", devotional: "Bondye pa dirije ou ak fòs men ak lanmou. Tankou yon bon papa, li gide ou ak dousè e tandres. Kòd lanmou li yo kenbe ou an sekirite san etoufman.", prayer: "Papa, mèsi paske ou gide m ak lanmou e dousè. Kòd lanmou ou kenbe m pre ou san fòse m. Amèn.", date: "" },
  { id: "181", verse: "Men pou Senyè a, mil an se tankou yon jou, e yon jou se tankou mil an.", reference: "2 Pyè 3:8", devotional: "Bondye pa opere sou menm kalandriye ak nou. Pasyans li enfini e lè li pafè. Lè ou santi Bondye an reta, sonje li wè tan yon fason diferan.", prayer: "Senyè, ede m konprann ke lè ou diferan de lè pa m. Ban m pasyans pou tann nan lè pafè ou. Amèn.", date: "" },
  { id: "182", verse: "Benediksyon pou moun ki kè pi, paske y a wè Bondye.", reference: "Matye 5:8", devotional: "Yon kè ki pi se sa ki pèmèt ou wè Bondye klèman. Lè kè ou lib de peche ak desepsyon, je espirityèl ou louvri pou wè Bondye nan tout bagay.", prayer: "Papa, pirifye kè m pou m ka wè ou. Retire tout sa ki anpeche m wè figi ou klèman. Amèn.", date: "" },
  { id: "183", verse: "Senyè a ap akonpli plan li gen pou mwen. Lanmou ou, Senyè, dire pou tout tan.", reference: "Sòm 138:8", devotional: "Bondye p ap abandone sa li kòmanse nan lavi ou. Li ap akonpli chak plan li gen pou ou paske lanmou li dire pou tout tan. Fè li konfyans pou fini sa li kòmanse.", prayer: "Senyè, mwen konnen ou ap akonpli plan ou gen pou mwen. Lanmou ou dire pou tout tan e ou p ap lage m. Amèn.", date: "" },
  { id: "184", verse: "Kite lang ou koupe peche, paske lavi ak lanmò nan pouvwa lang.", reference: "Pwovèb 18:21", devotional: "Pawòl ou gen yon pouvwa enòm. Yo ka bay lavi oswa bay lanmò. Chwazi pale pawòl ki ankouraje, ki edifye e ki bay lavi a moun ki bò kote ou.", prayer: "Senyè, ede m pale pawòl ki bay lavi. Kite lang mwen se yon zouti pou ankourajman e benediksyon. Amèn.", date: "" },
  { id: "185", verse: "Lè nou prale travèse dlo, m ap avèk ou. Lè ou prale travèse rivyè, yo p ap bwaye ou.", reference: "Ezayi 43:2", devotional: "Nan moman ki pi difisil nan lavi a, Bondye la avèk ou. Dlo a ka wo, men li p ap bwaye ou. Dife a ka cho, men li p ap boule ou. Prezans li se garanti ou.", prayer: "Senyè, lè m ap travèse dlo difisil yo, ou avèk mwen. Mwen p ap bwaye paske ou kenbe m. Amèn.", date: "" },
  { id: "186", verse: "Mwen menm, mwen kouri vin jwenn ou tankou yon sèf k ap chache dlo nan sous la.", reference: "Sòm 42:1", devotional: "Gen yon swaf espirityèl ki sèlman Bondye ka satisfè. Tankou yon sèf ki bezwen dlo pou siviv, nanm ou bezwen prezans Bondye. Kouri bò kote li ak tout dezi ou.", prayer: "Papa, nanm mwen swaf pou ou tankou yon sèf swaf pou dlo. Satisfè dezi m nan prezans ou. Amèn.", date: "" },
  { id: "187", verse: "Si lèzòm di yo pa gen peche, y ap twonpe tèt yo, e verite a pa nan yo.", reference: "1 Jan 1:8", devotional: "Onètete devan Bondye se premye pa nan gras li. Rekonèt peche ou pa yon feblès men yon fòs paske sa louvri pòt padon ak gerizon.", prayer: "Senyè, mwen pa pretann mwen san peche. Mwen rekonèt bezwen m pou gras ou. Padone m epi netwaye m. Amèn.", date: "" },
  { id: "188", verse: "Paske volonte Bondye a, se sa ki bon, sa ki agreyab, sa ki pafè.", reference: "Women 12:2b", devotional: "Volonte Bondye se toujou sa ki pi bon pou ou. Li pa bon sèlman, li agreyab e pafè. Lè ou soumèt bay volonte li, ou dekouvri plan li depase rèv pa ou.", prayer: "Papa, ede m dekouvri e aksepte volonte ou ki bon, agreyab e pafè pou lavi m. Amèn.", date: "" },
  { id: "189", verse: "Se pou nou rete konekte ak mwen, e mwen menm m ap rete konekte ak nou.", reference: "Jan 15:4", devotional: "Kris envite ou nan yon relasyon entim ki dire. Rete konekte ak li se kle pou bay fwi nan lavi ou. San koneksyon sa a, pa gen kwasans espirityèl.", prayer: "Jezi, mwen vle rete konekte ak ou chak jou. San ou, mwen pa ka fè anyen ki gen valè etènèl. Amèn.", date: "" },
  { id: "190", verse: "Mwen pa wont Bòn Nouvèl la, paske se pouvwa Bondye pou delivrans tout moun ki kwè.", reference: "Women 1:16", devotional: "Levanjil la se pouvwa Bondye ki delivre. Pa janm wont pataje li paske li gen kapasite chanje lavi pou tout tan. Li se mesaj espwa pou tout moun ki kwè.", prayer: "Senyè, mwen pa wont levanjil la. Ban m kouraj pou pataje li ak tout moun. Li se pouvwa ou pou delivrans. Amèn.", date: "" },
  { id: "191", verse: "Chache Senyè a pandan ou ka jwenn li. Rele non li pandan li toupre.", reference: "Ezayi 55:6", devotional: "Pa tann demen pou chache Bondye. Jodi a se jou a. Li toupre ou kounye a, pare pou reponn. Sezi opòtinite sa a pou apwofondi relasyon ou ak li.", prayer: "Senyè, mwen chache ou jodi a pandan m ka jwenn ou. Mwen rele non ou pandan ou toupre. Vin jwenn mwen. Amèn.", date: "" },
  { id: "192", verse: "Kè kontan pou moun y ap pèsekite poutèt jistis, paske wayòm syèl la se pou yo.", reference: "Matye 5:10", devotional: "Soufri pou sa ki jis pa yon malediksyon men yon benediksyon. Wayòm syèl la se pou moun ki kanpe fèm nan verite Bondye menm lè sa koute yo.", prayer: "Senyè, ban m kouraj pou kanpe pou jistis menm lè sa koute m. Wayòm ou se rekonpans mwen. Amèn.", date: "" },
  { id: "193", verse: "Gras ak ou e lapè soti nan Bondye Papa nou ak Senyè Jezikri.", reference: "Women 1:7", devotional: "Gras ak lapè se kado Bondye bay tout moun ki nan Kris. Pa sèlman pou kèk moun espesyal men pou ou jodi a. Resevwa gras ak lapè li.", prayer: "Papa, mwen resevwa gras ak lapè ou jodi a. Mèsi ke yo disponib pou mwen nan Jezikri. Amèn.", date: "" },
  { id: "194", verse: "Fè atansyon ak kè nou anwo tout bagay, paske se nan li sous lavi a soti.", reference: "Pwovèb 4:23b", devotional: "Kè ou se sous tout sa ki soti nan lavi ou. Sa ou pèmèt antre nan kè ou ap detèmine kalite lavi ou. Veye sou li ak dilijans epi nouri li ak Pawòl Bondye.", prayer: "Papa, ede m veye sou kè m anwo tout bagay. Kite Pawòl ou nouri kè m epi gide lavi m. Amèn.", date: "" },
  { id: "195", verse: "Mwen rele Senyè a e li reponn mwen. Li delivre m nan tout sa m te pè.", reference: "Sòm 34:4b", devotional: "Bondye se Bondye ki reponn lapriyè. Lè ou rele li, li pa inyore ou. Li tande, li aji e li delivre ou nan tout sa ki fè ou pè.", prayer: "Senyè, mwen rele ou e mwen fè ou konfyans pou reponn mwen. Delivre m nan tout laperèz mwen. Amèn.", date: "" },
  { id: "196", verse: "Pa gen kondanasyon pou moun ki nan Jezikri.", reference: "Women 8:1", devotional: "Nan Kris, ou lib de kondanasyon. Pa gen akizasyon ki ka kenbe kont ou paske Jezi te peye dèt la nèt. Mache nan libète sa a jodi a.", prayer: "Senyè Jezi, mèsi ke pa gen kondanasyon pou mwen nan ou. Ede m mache nan libète sa a san kilpabilite. Amèn.", date: "" },
  { id: "197", verse: "Senyè a ap kenbe tout moun ki tonbe epi li leve tout moun ki koube.", reference: "Sòm 145:14", devotional: "Lè ou tonbe, Bondye pa kondane ou men li kenbe ou. Lè ou koube anba chay, li leve ou. Li se Bondye ki restore e ki releve moun ki nan bezwen.", prayer: "Papa, lè m tonbe, kenbe m. Lè m koube, leve m. Ou se Bondye ki restore e ki releve. Amèn.", date: "" },
  { id: "198", verse: "Bay e y ap ba ou; yon bon mezi, byen peze, byen souke, k ap debòde.", reference: "Lik 6:38", devotional: "Jenerozite ouvri pòt pou resevwa plis. Lè ou bay ak kè kontan, Bondye bay ou retou nan mezi ki debòde. Prensip semans ak rekòt toujou mache.", prayer: "Senyè, fè m yon moun ki jenerè. Mwen fè ou konfyans ke lè m bay, ou ap bay m retou nan mezi ki debòde. Amèn.", date: "" },
  { id: "199", verse: "Mache selon lespri a e nou p ap akonpli dezi lachè a.", reference: "Galat 5:16", devotional: "Sekrè pou genyen sou tantasyon se mache selon Lespri a. Lè Lespri Bondye gide ou, dezi lachè a pèdi pouvwa li sou ou. Soumèt ou bay Lespri li chak jou.", prayer: "Sentespri, gide m pou m mache selon ou chak jou. Ede m pa akonpli dezi lachè a men viv pou ou. Amèn.", date: "" },
  { id: "200", verse: "Moun Bondye ki fè nou konfyans yo, tout bagay posib pou yo.", reference: "Mak 9:23", devotional: "Lafwa louvri pòt posibilite san limit. Bondye pa mande yon lafwa pafè men yon lafwa sensè. Menm yon ti grenn lafwa ka debloke mirak nan lavi ou.", prayer: "Senyè, mwen kwè! Ede m kote lafwa m fèb. Ak ou tout bagay posib. Amèn.", date: "" },
  { id: "201", verse: "Ann fè sa ki byen pou tout moun, espesyalman pou moun ki nan fanmi lafwa a.", reference: "Galat 6:10", devotional: "Bonte pa dwe gen limit, men li dwe kòmanse ak fanmi lafwa a. Fè byen pou tout moun se yon fason pou reflete karaktè Papa ou ki nan syèl la.", prayer: "Papa, ede m fè byen pou tout moun, espesyalman pou frè ak sè m yo nan lafwa. Amèn.", date: "" },
  { id: "202", verse: "Men Senyè a fidèl, e l ap fèmize nou e pwoteje nou kont sa ki mal.", reference: "2 Tesalonisyen 3:3b", devotional: "Fidelite Bondye se garanti ou kont tout mal. Li pa sèlman pwomèt pwoteksyon men li aji sou li. Konfyans ou nan li pa janm dezapwente.", prayer: "Senyè fidèl, mèsi ke ou fèmize m e pwoteje m kont tout mal. Konfyans mwen nan ou solid. Amèn.", date: "" },
  { id: "203", verse: "Lè yon moun gen sajès, sa parèt nan konduit li. Lè yon moun gen bon sans, sa parèt nan sa l ap fè.", reference: "Pwovèb 14:8", devotional: "Vrè sajès parèt nan aksyon, pa sèlman nan pawòl. Lè ou aplike sajès Bondye nan lavi chak jou ou, moun ka wè diferans lan. Sajès se yon bagay pratik.", prayer: "Papa, ban m sajès ki parèt nan konduit mwen. Kite bon sans ou gide tout sa m ap fè. Amèn.", date: "" },
  { id: "204", verse: "Bondye se lanmou.", reference: "1 Jan 4:8", devotional: "Bondye pa sèlman gen lanmou, li se lanmou li menm. Tout sa li fè soti nan lanmou. Lè ou konnen Bondye, ou konnen lanmou nan fòm li ki pi pi e pi bèl.", prayer: "Papa, ou se lanmou li menm. Ede m konnen ou pi pwofon e reflete lanmou ou nan tout sa m fè. Amèn.", date: "" },
  { id: "205", verse: "Menm jan syèl la wo sou tè a, se konsa lanmou li gran pou moun ki gen krentif pou li.", reference: "Sòm 103:11", devotional: "Lanmou Bondye san limit. Li wo tankou syèl la wo sou tè a. Ou pa ka depase lanmou li e ou pa ka tonbe anba li. Ou envelòpe nan lanmou enfini li.", prayer: "Senyè, lanmou ou gran e san limit. Mèsi ke mwen pa ka janm tonbe anba lanmou ou. Amèn.", date: "" },
  { id: "206", verse: "Mwen gen yon plan pou nou, se Senyè a ki di sa, se pa plan pou malè, men plan pou ba ou yon avni ak yon espwa.", reference: "Jeremi 29:11b", devotional: "Plan Bondye pou ou toujou pou byen ou, janm pou mal. Li bay ou yon avni ak yon espwa. Menm nan moman difisil, plan li toujou ap travay pou ou.", prayer: "Papa, mèsi pou plan ou ki gen espwa ak yon bèl avni pou mwen. Mwen fè ou konfyans ak chak jou. Amèn.", date: "" },
  { id: "207", verse: "Kite tout moun konnen jan nou janti. Senyè a pre.", reference: "Filipyen 4:5", devotional: "Jantiyès ou se yon temwayaj pou mond lan ke Senyè a pre. Lè moun wè dousè ak bonte nan ou, yo wè Kris. Viv ak jantiyès chak jou.", prayer: "Senyè, ede m montre jantiyès a tout moun. Kite yo wè ou nan fason m trete lòt moun. Amèn.", date: "" },
  { id: "208", verse: "Mete tout bagay nan men Bondye lè n ap lapriyè, e lapè Bondye a va veye sou kè nou.", reference: "Filipyen 4:6-7", devotional: "Lapriyè se chemen ki mennen nan lapè Bondye. Lè ou mete tout bagay nan men li, li ranplase enkyetid ak yon lapè ki depase konpreyansyon.", prayer: "Papa, mwen mete tout bagay nan men ou nan lapriyè. Kite lapè ou veye sou kè m ak panse m. Amèn.", date: "" },
  { id: "209", verse: "Senyè a ap ban nou sa ki bon, e tè nou ap bay fwi li.", reference: "Sòm 85:12", devotional: "Bondye se sous tout sa ki bon. Li pwomèt beni tè ou, efò ou ak travay ou. Lè li bay sa ki bon, tout sa ou fè bay fwi.", prayer: "Senyè, ban mwen sa ki bon e kite travay mwen bay fwi pou glwa ou. Amèn.", date: "" },
  { id: "210", verse: "Paske se avèk kè moun kwè pou yo ka jis, e se avèk bouch yo konfese pou yo ka sove.", reference: "Women 10:10", devotional: "Delivrans se yon aksyon kè ak bouch. Ou kwè nan kè ou e ou konfese ak bouch ou. Lafwa ak deklarasyon mache ansanm nan chemen delivrans.", prayer: "Senyè, mwen kwè nan kè m e mwen konfese ak bouch mwen ke Jezi se Senyè. Mèsi pou delivrans mwen. Amèn.", date: "" },
  { id: "211", verse: "Fè lwanj Senyè a, paske li bon, lanmou li dire pou tout tan.", reference: "Sòm 107:1", devotional: "Bonte Bondye merite lwanj san rete. Lanmou li pa gen fen e li pa gen kondisyon. Chak jou se yon nouvo rezon pou fè li lwanj.", prayer: "Senyè, mwen fè ou lwanj paske ou bon. Lanmou ou dire pou tout tan e mwen rekonesan. Amèn.", date: "" },
  { id: "212", verse: "Nan mond lan n ap gen tribilasyon. Men pran kouraj! Mwen gen laviktwa sou mond lan.", reference: "Jan 16:33b", devotional: "Jezi pa kache reyalite soufrans nan mond sa a, men li deklare viktwa final. Ou ka pran kouraj paske batay la deja genyen. Viv kòm yon moun ki gen laviktwa.", prayer: "Jezi, mwen pran kouraj jodi a paske ou gen laviktwa sou mond lan. Mwen viv kòm yon venkè nan ou. Amèn.", date: "" },
  { id: "213", verse: "Koute konsèy e aksepte disiplin pou ou ka vin saj nan rès lavi ou.", reference: "Pwovèb 19:20", devotional: "Sajès grandi lè ou louvri pou resevwa konsèy ak disiplin. Pa rejte koreksyon men aksepte li kòm yon kado ki fè ou vin pi bon. Imilite louvri pòt sajès.", prayer: "Papa, ban m yon kè ki louvri pou resevwa konsèy ak disiplin. Fè m vin saj nan rès lavi m. Amèn.", date: "" },
  { id: "214", verse: "Pitit mwen yo, ann pa renmen ak pawòl sèlman ni ak lang, men ak aksyon e verite.", reference: "1 Jan 3:18", devotional: "Vrè lanmou pa rete nan pawòl men li montre nan aksyon. Bondye rele nou pou demontre lanmou nan fason konkrep ak otantik. Aksyon pale pi fò pase pawòl.", prayer: "Senyè, ede m renmen pa ak pawòl sèlman men ak aksyon reyèl e verite. Kite lanmou m parèt nan sa m fè. Amèn.", date: "" },
  { id: "215", verse: "Fè Senyè a konfyans e fè sa ki byen. Rete nan peyi a e jwi sekirite.", reference: "Sòm 37:3", devotional: "Konfyans nan Bondye ak aksyon ki bon mache ansanm. Fè li konfyans pa sèlman nan pawòl men montre sa nan fason ou viv. Li pwomèt sekirite pou moun ki mache fidèlman.", prayer: "Senyè, mwen fè ou konfyans e mwen ap fè sa ki byen. Ban m sekirite pandan m ap mache fidèlman. Amèn.", date: "" },
  { id: "216", verse: "Bondye renmen moun ki bay ak kè kontan.", reference: "2 Korentyen 9:7", devotional: "Bay pa dwe yon obligasyon men yon ekspresyon kè kontan. Lè ou bay ak kè kontan, sa touche kè Bondye. Li pran plezi nan jenerozite ki soti nan lanmou, pa nan presyon.", prayer: "Papa, fè m yon moun ki bay ak kè kontan. Kite jenerozite m soti nan lanmou, pa nan obligasyon. Amèn.", date: "" },
  { id: "217", verse: "Tou sa m mande nan lapriyè, mwen kwè m ap resevwa li.", reference: "Mak 11:24", devotional: "Lapriyè ak lafwa se yon konbinezon ki louvri pòt syèl la. Jezi anseye nou mande nan konfyans, kwè ke Bondye ap reponn. Lafwa se kle ki louvri pwomès Bondye.", prayer: "Senyè, mwen priye ak lafwa, kwè ke ou ap reponn. Ede m mande ak konfyans nan bonte ou. Amèn.", date: "" },
  { id: "218", verse: "Yon lang ki dous se yon pyebwa lavi, men yon lang ki kwochi kraze lespri.", reference: "Pwovèb 15:4", devotional: "Pawòl dous gen pouvwa bay lavi ak gerizon. Men pawòl ki kras ka kraze yon moun. Chwazi pale ak dousè e gade kijan sa chanje relasyon ou yo.", prayer: "Papa, mete yon lang dous nan bouch mwen. Kite pawòl mwen se yon pyebwa lavi pou tout moun bò kote m. Amèn.", date: "" },
  { id: "219", verse: "Se pa pa volonte lachè, ni pa volonte yon gason, men se Bondye ki fè yo tounen pitit li.", reference: "Jan 1:13", devotional: "Vin pitit Bondye pa depann de efò imen men de pouvwa Bondye. Se li ki fè transfòmasyon sa a posib pa gras li. Delivrans se travay Bondye nan ou.", prayer: "Papa, mèsi ke m se pitit ou pa volonte ou, pa efò imen. Delivrans mwen se travay gras ou. Amèn.", date: "" },
  { id: "220", verse: "Mwen mande Senyè a yon sèl bagay, se sa m ap chache: pou m rete nan kay Senyè a tout jou lavi m.", reference: "Sòm 27:4", devotional: "Pi gwo dezi nan lavi a ta dwe prezans Bondye. David te konprann ke anyen pa ka konpare ak rete nan prezans Senyè a. Fè prezans li priyorite ou tou.", prayer: "Senyè, yon sèl bagay mwen mande: rete nan prezans ou tout jou lavi m. Pa gen anyen ki pi presye pase sa. Amèn.", date: "" },
  { id: "221", verse: "Sonje mèvèy li te fè, mirak li ak jijman li te pronose.", reference: "Sòm 105:5", devotional: "Sonje sa Bondye te fè nan pase ranfòse lafwa ou pou avni. Lè ou medite sou fidèlite li, konfyans ou grandi. Pa janm bliye mèvèy Senyè a.", prayer: "Senyè, mwen sonje mèvèy ou te fè nan lavi m. Fidèlite ou nan pase ban m konfyans pou avni. Amèn.", date: "" },
  { id: "222", verse: "Se pou nou gen pasyans nan soufrans, toujou ap priye.", reference: "Women 12:12", devotional: "Pasyans nan soufrans e pèseverans nan lapriyè mache ansanm. Lè ou soufri, priye. Lè ou priye, gen pasyans. Bondye ap travay nan de a anmenm tan.", prayer: "Papa, ban m pasyans nan soufrans ak pèseverans nan lapriyè. Mwen fè ou konfyans nan tout eprèv. Amèn.", date: "" },
  { id: "223", verse: "Krentif Senyè a se kòmansman sajès.", reference: "Pwovèb 9:10", devotional: "Tout vrè sajès kòmanse ak yon respè pwofon pou Bondye. Lè ou rekonèt grandè li e soumèt bay li, ou ouvri pòt pou vrè konesans ak konpreyansyon.", prayer: "Senyè, mwen gen krentif pou ou ki se kòmansman sajès. Ouvri je m pou konprann verite ou. Amèn.", date: "" },
  { id: "224", verse: "E lapè Kris la renye nan kè nou, paske se pou sa nou te rele nan yon sèl kò.", reference: "Kolosyen 3:15", devotional: "Kite lapè Kris la pran kontwòl kè ou e gide desizyon ou. Lè lapè li renye anndan ou, sa afekte tout sa ou fè ak tout relasyon ou.", prayer: "Senyè, kite lapè Kris la renye nan kè m. Gide desizyon m ak relasyon m pa lapè ou. Amèn.", date: "" },
  { id: "225", verse: "Yon bon zanmi renmen nan tout tan, e yon frè fèt pou jou malè.", reference: "Pwovèb 17:17", devotional: "Vrè zanmitay teste nan moman difisil. Yon bon zanmi la nan bon tan ak move tan. Bondye mete moun nan lavi ou pou soutni ou. Apresye yo e se yon zanmi fidèl tou.", prayer: "Papa, mèsi pou bon zanmi ou mete nan lavi m. Ede m vin yon zanmi fidèl ki renmen nan tout tan. Amèn.", date: "" },
  { id: "226", verse: "Se konsa, pitit mwen yo, kanpe fèm, pa branle, toujou ap travay di nan travay Senyè a.", reference: "1 Korentyen 15:58", devotional: "Kanpe fèm nan lafwa e pa janm lage travay Senyè a. Efò ou pou Bondye pa janm vid. Tout sa ou fè pou li gen yon rekonpans etènèl.", prayer: "Senyè, ede m kanpe fèm e pa janm lage travay ou. Mwen konnen travay mwen nan ou pa janm vid. Amèn.", date: "" },
  { id: "227", verse: "Mwen fè tout bagay pou levanjil la, pou m ka patisipe nan benediksyon li yo.", reference: "1 Korentyen 9:23", devotional: "Viv pou levanjil la se pi gwo apèl ou ka resevwa. Lè ou dedye lavi ou pou bon nouvèl Kris la, ou patisipe nan benediksyon ki pa gen limit.", prayer: "Papa, ede m viv totalman pou levanjil la. Mwen vle patisipe nan benediksyon li yo e pataje yo ak lòt moun. Amèn.", date: "" },
  { id: "228", verse: "Men li di m: Gras mwen kont pou ou, paske nan feblès se la pouvwa m parèt pi byen.", reference: "2 Korentyen 12:9", devotional: "Feblès ou se opòtinite pou pouvwa Bondye briye. Li pa mande ou vin pafè men soumèt feblès ou ba li. Gras li ase pou tout sa ou bezwen.", prayer: "Senyè, gras ou ase pou mwen. Nan feblès mwen, kite pouvwa ou parèt pi byen. Amèn.", date: "" },
  { id: "229", verse: "Pa vanje tèt nou, zanmi m yo, men kite sa pou kòlè Bondye.", reference: "Women 12:19", devotional: "Vanjans se pa travay ou men travay Bondye. Li konnen kijan pou jere enjistis pi byen pase ou. Kite li defann ou e padone moun ki fè ou mal.", prayer: "Papa, mwen kite vanjans nan men ou. Ede m padone e fè ou konfyans pou defann mwen. Amèn.", date: "" },
  { id: "230", verse: "Pa bay moun ki mal mal, men genyen mal la ak sa ki bon.", reference: "Women 12:21", devotional: "Repons Bondye a mal se pa plis mal men sa ki bon. Lè ou reponn mal ak bonte, ou brize sik la e ou briye limyè Kris nan yon sitiyasyon ki fè nwa.", prayer: "Senyè, ede m pa bay mal pou mal men genyen mal la ak sa ki bon. Kite bonte ou briye nan mwen. Amèn.", date: "" },
  { id: "231", verse: "Priye san rete.", reference: "1 Tesalonisyen 5:17", devotional: "Lapriyè pa dwe yon evènman men yon fason viv. Rete nan konvèsasyon konstan ak Bondye nan tout sa ou fè. Li toujou ap tande e li toujou la.", prayer: "Papa, ede m priye san rete. Kite lavi m vin yon konvèsasyon konstan ak ou. Amèn.", date: "" },
  { id: "232", verse: "Mwen gen tout pouvwa nan syèl la ak sou tè a.", reference: "Matye 28:18", devotional: "Jezi gen tout otorite nan syèl ak sou tè. Pa gen sitiyasyon ki pi wo pase pouvwa li. Fè li konfyans paske li gen kontwòl sou tout bagay.", prayer: "Senyè Jezi, ou gen tout pouvwa nan syèl la ak sou tè a. Mwen soumèt ba ou paske ou gen kontwòl. Amèn.", date: "" },
  { id: "233", verse: "Ann apwoche twòn gras la ak asirans pou nou ka jwenn mizèrikòd e gras nan lè bezwen.", reference: "Ebre 4:16", devotional: "Twòn Bondye pa yon twòn jijman men yon twòn gras. Ou ka vini ak asirans, san laperèz, pou jwenn sa ou bezwen nan bon moman.", prayer: "Papa, mwen apwoche twòn gras ou ak asirans. Ban m mizèrikòd ak gras nan lè bezwen m nan. Amèn.", date: "" },
  { id: "234", verse: "Mwen bay bann mouton m yo lavi ki p ap janm fini, yo p ap janm peri, e pèsonn pa ka rache yo nan men m.", reference: "Jan 10:28", devotional: "Sekirite ou nan Kris se total e etènèl. Pèsonn ni anyen pa ka rache ou nan men li. Ou solid nan lanmou li ki pa janm lage ou.", prayer: "Jezi, mèsi ke ou ban m lavi etènèl e pèsonn pa ka rache m nan men ou. Mwen an sekirite nan ou. Amèn.", date: "" },
  { id: "235", verse: "Yon repons dou kalme kòlè, men yon pawòl ki di leve fache.", reference: "Pwovèb 15:1", devotional: "Fason ou reponn gen pouvwa kalme oswa agrave yon sitiyasyon. Pawòl dous gen pouvwa pou dezame kòlè pandan pawòl di ajoute lwiil sou dife.", prayer: "Papa, mete pawòl dous nan bouch mwen. Ede m reponn ak dousè ki kalme kòlè olye agrave l. Amèn.", date: "" },
  { id: "236", verse: "Senyè a beni kay moun ki jis.", reference: "Pwovèb 3:33", devotional: "Benediksyon Bondye rete sou moun ki viv nan jistis. Kay ou, fanmi ou ak tout sa ou gen ka resevwa benediksyon li lè ou mache fidèlman ak li.", prayer: "Senyè, beni kay mwen ak fanmi m. Ede m viv nan jistis pou benediksyon ou ka rete sou nou. Amèn.", date: "" },
  { id: "237", verse: "Si nou gen lafwa gwo tankou yon grenn moutad, n ap di mòn sa a: deplase, e l ap deplase.", reference: "Matye 17:20", devotional: "Menm ti lafwa gen gwo pouvwa. Pa dekouraje paske lafwa ou parèt piti. Bondye pa mande gwo lafwa men lafwa sensè. Ak li, mòn ka deplase.", prayer: "Senyè, menm si lafwa m piti tankou yon grenn moutad, mwen kwè nan pouvwa ou pou deplase mòn yo. Amèn.", date: "" },
  { id: "238", verse: "Bondye pa voye Pitit li nan mond lan pou kondane mond lan, men pou mond lan ka sove pa li.", reference: "Jan 3:17", devotional: "Misyon Jezi pa t kondanasyon men delivrans. Li te vini pou sove, pa pou detwi. Resevwa lanmou li e pa kite kondanasyon kenbe ou lwen li.", prayer: "Jezi, mèsi ke ou pa t vini pou kondane men pou sove. Mwen resevwa delivrans ou ak kè rekonesan. Amèn.", date: "" },
  { id: "239", verse: "Moun ki gen yon bon kè pale bon bagay paske se bon bagay ki nan kè li.", reference: "Matye 12:35", devotional: "Sa ki nan kè ou se sa ki soti nan bouch ou. Yon kè ki plen ak bonte Bondye pwodui pawòl ki ankouraje ak edifye. Nouri kè ou ak bon bagay.", prayer: "Senyè, ranpli kè m ak bon bagay pou pawòl mwen ka reflete bonte ou. Amèn.", date: "" },
  { id: "240", verse: "Senyè a, Bondye ou la, te chwazi ou pami tout pèp ki sou latè pou ou vin yon pèp espesyal pou li.", reference: "Detewonòm 7:6", devotional: "Bondye te chwazi ou pou yon relasyon espesyal ak li. Ou pa te chwazi li an premye, se li ki te chwazi ou. Sa montre valè ou gen nan je li.", prayer: "Papa, mèsi ke ou te chwazi m pou m vin yon moun espesyal pou ou. Ede m viv diy de apèl ou. Amèn.", date: "" },
  { id: "241", verse: "Poze konfyans ou sou Senyè a pou tout tan, paske Senyè a se yon wòch ki la pou tout tan.", reference: "Ezayi 26:4", devotional: "Bondye se yon fondasyon etènèl ki pa janm chanje. Ou ka poze konfyans ou sou li pou tout tan paske li se wòch ki la pou tout tan.", prayer: "Senyè, mwen poze konfyans mwen sou ou pou tout tan. Ou se wòch etènèl ki pa janm bouje. Amèn.", date: "" },
  { id: "242", verse: "M ap mache devan Senyè a nan peyi moun vivan yo.", reference: "Sòm 116:9", devotional: "Bondye vle ou viv yon lavi plen ak siyifikatif, pa sèlman siviv. Mache devan li nan peyi moun vivan yo vle di viv ak lafwa, espwa e detèminasyon.", prayer: "Senyè, mwen vle mache devan ou nan peyi moun vivan yo. Kite lavi m plen ak siyifikasyon e objektif. Amèn.", date: "" },
  { id: "243", verse: "Se pou tout moun konn jan nou janti. Senyè a pre.", reference: "Filipyen 4:5b", devotional: "Jantiyès ou se yon refleksyon Kris anndan ou. Lè moun wè dousè ou, yo wè yon moun ki konnen Senyè a pre. Jantiyès se yon temwayaj pisan.", prayer: "Papa, kite jantiyès mwen temwanye ke Senyè a pre. Ede m trete tout moun ak dousè. Amèn.", date: "" },
  { id: "244", verse: "Mwen menm, mwen se rezirèksyon an ak lavi a. Moun ki kwè nan mwen va viv, menm si li ta mouri.", reference: "Jan 11:25", devotional: "Jezi gen pouvwa sou lanmò li menm. Rezirèksyon li se garanti ke tout moun ki kwè nan li ap viv pou tout tan. Lanmò pa gen dènye mo nan Kris.", prayer: "Jezi, ou se rezirèksyon an ak lavi a. Mwen kwè nan ou e mwen gen lavi etènèl. Lanmò pa gen pouvwa sou mwen. Amèn.", date: "" },
  { id: "245", verse: "Youn pote chay lòt, e nan fason sa a nou akonpli lwa Kris la.", reference: "Galat 6:2", devotional: "Bondye pa t fè ou pou viv poukont ou. Li rele nou pou pote chay youn lòt. Lè ou ede yon frè oswa yon sè ki nan bezwen, ou akonpli lwa lanmou Kris la.", prayer: "Senyè, ede m pote chay frè ak sè m yo. Kite m vin yon sous ankourajman ak sipò pou lòt moun. Amèn.", date: "" },
  { id: "246", verse: "Se pa moun ki di m Senyè, Senyè ki pral antre nan wayòm syèl la, men se moun ki fè volonte Papa m ki nan syèl la.", reference: "Matye 7:21", devotional: "Bondye gade plis pase pawòl ou; li gade aksyon ou. Vrè disipila se pa sèlman rele Jezi Senyè men fè volonte Papa a nan lavi chak jou.", prayer: "Senyè, mwen pa vle sèlman di pawòl men fè volonte Papa a. Ede m viv sa m kwè. Amèn.", date: "" },
  { id: "247", verse: "Si Senyè a pa bati kay la, moun k ap bati l yo ap travay pou anyen.", reference: "Sòm 127:1", devotional: "San benediksyon ak gidaj Bondye, tout efò imen vid. Kite Bondye bati kay ou, fanmi ou ak lavi ou. Lè li nan sant la, tout bagay chita sou bon fondasyon.", prayer: "Senyè, bati kay mwen ak lavi m. San ou, efò m yo vid. Ak ou, tout bagay gen siyifikasyon. Amèn.", date: "" },
  { id: "248", verse: "Mwen pral prepare yon plas pou nou. Si m ale prepare yon plas, m ap retounen vin chache nou.", reference: "Jan 14:2-3", devotional: "Jezi ale prepare yon kote pafè pou ou nan syèl. Li ap retounen vin chache ou pou ou ka la kote li ye pou tout tan. Sa se espwa etènèl ou.", prayer: "Jezi, mèsi pou plas ou ap prepare pou mwen. Mwen tann retou ou ak kè kontan e espwa. Amèn.", date: "" },
  { id: "249", verse: "Li pini moun li renmen yo, menm jan yon papa pini pitit li renmen.", reference: "Pwovèb 3:12", devotional: "Disiplin Bondye se yon ekspresyon lanmou, pa kòlè. Tankou yon bon papa ki korije pitit li paske li renmen li, Bondye korije ou paske li vle pi bon pou ou.", prayer: "Papa, mèsi ke ou korije m paske ou renmen m. Ede m aksepte disiplin ou ak imilite e rekonesans. Amèn.", date: "" },
  { id: "250", verse: "Nou se tè a, se nan pousyè Bondye te fè nou, e se nan pousyè n ap retounen.", reference: "Jenèz 3:19", devotional: "Sonje orijin nou anseye imilite. Nou se kreyati frajil ki depann totalman de Kreyatè a. Men nan frajilite sa a, Bondye mete yon valè enfini.", prayer: "Bondye, mwen sonje ke m se pousyè, men ou te kreye m ak lanmou enfini. Nan imilite m, mwen glorifye ou. Amèn.", date: "" },
  { id: "251", verse: "M ap kenbe fèm, m ap kanpe san deplase, toujou ap travay pi di nan sèvis Senyè a.", reference: "1 Korentyen 15:58b", devotional: "Pèseverans nan sèvis Bondye gen rekonpans etènèl. Pa lage, pa dekouraje. Kenbe fèm nan sa ou kwè e travay di pou Senyè a ak detèminasyon.", prayer: "Senyè, ede m kenbe fèm e pa deplase nan sèvis ou. Mwen ap travay di konnen ke rekonpans ou sèten. Amèn.", date: "" },
  { id: "252", verse: "Mwen leve bonè, m kriye pou sekou; mwen mete espwa m nan pawòl ou.", reference: "Sòm 119:147", devotional: "Kòmanse chak jou nan lapriyè e nan Pawòl Bondye se pi bon fason pou prepare pou sa ki devan ou. Lè ou mete espwa ou nan pawòl li, ou jwenn fòs pou chak jou.", prayer: "Senyè, chak maten mwen vini bò kote ou nan lapriyè. Mwen mete espwa m nan pawòl ou pou jou a. Amèn.", date: "" },
  { id: "253", verse: "Lè Lespri verite a vini, li va gide nou nan tout verite.", reference: "Jan 16:13", devotional: "Sentespri a se gid ou nan tout verite. Li pa kite ou nan konfizyon men li klere lespri ou pou konprann volonte Bondye ak Pawòl li.", prayer: "Sentespri, gide m nan tout verite. Klere lespri m pou m ka konprann volonte Bondye e mache ladan l. Amèn.", date: "" },
  { id: "254", verse: "Nou pa gen batay kont san ak chè, men kont fòs espirityèl ki nan syèl la.", reference: "Efezyen 6:12", devotional: "Batay ou yo pa sèlman fizik men espirityèl. Lènmi reyèl la pa moun men fòs espirityèl. Prepare ou ak zam espirityèl Bondye ba ou pou goumen.", prayer: "Papa, louvri je m pou m wè batay espirityèl la. Ekipe m ak zam ou pou m ka kanpe fèm. Amèn.", date: "" },
  { id: "255", verse: "Mwen konnen ke Redanmtè m vivan e ke nan dènye jou a li va kanpe sou tè a.", reference: "Jòb 19:25", devotional: "Menm nan mitan soufrans, lafwa nan yon Redanmtè vivan ba ou espwa. Jòb te konnen sa e ou ka konnen li tou. Redanmtè ou vivan e li ap retounen.", prayer: "Senyè, mwen konnen ke Redanmtè m vivan. Nan tout soufrans, espwa m nan ou rete fèm. Amèn.", date: "" },
  { id: "256", verse: "Mwen menm mwen konn moun m mete konfyans mwen an e mwen sèten li kapab kenbe sa m konfye ba li jouk jou sa a.", reference: "2 Timote 1:12", devotional: "Konfyans nan Bondye pa baze sou avèglite men sou konesans li. Lè ou konnen ki moun Bondye ye, ou ka konfye tout bagay nan men li san laperèz.", prayer: "Papa, mwen konnen ki moun mwen fè konfyans. Mwen sèten ou ka kenbe tout sa m konfye ba ou. Amèn.", date: "" },
  { id: "257", verse: "Ala bèl sa bèl, ala bon li bon, lè frè rete ansanm!", reference: "Sòm 133:1", devotional: "Inite nan fanmi Bondye se yon benediksyon ekstraòdinè. Lè kwayan viv ansanm nan lanmou ak lapè, sa glorifye Bondye e pote benediksyon sou tout moun.", prayer: "Senyè, beni kominote lafwa a ak inite. Kite nou viv ansanm nan lanmou ki glorifye non ou. Amèn.", date: "" },
  { id: "258", verse: "Nou pa sove pa zèv nou men pa gras Bondye atravè lafwa.", reference: "Efezyen 2:8-9", devotional: "Pa gen anyen ou ka fè pou merite delivrans. Se yon kado gratis Bondye ba ou pa gras. Aksepte li ak rekonesans e viv nan libète sa a chak jou.", prayer: "Papa, mèsi ke delivrans mwen se yon kado gras ou, pa zèv pa m. Mwen aksepte ak rekonesans e imilite. Amèn.", date: "" },
  { id: "259", verse: "Konsa tou, lafwa, si li pa gen zèv, li mouri nèt.", reference: "Jak 2:17", devotional: "Lafwa san aksyon pa gen vi. Vrè lafwa toujou manifeste nan aksyon konkrep. Sa ou kwè dwe parèt nan fason ou viv e nan sa ou fè pou lòt moun.", prayer: "Senyè, kite lafwa m gen vi. Ede m manifeste sa m kwè nan aksyon konkrep chak jou. Amèn.", date: "" },
  { id: "260", verse: "Bondye, ou se Bondye mwen, mwen chache ou bonè. Nanm mwen swaf pou ou.", reference: "Sòm 63:1", devotional: "Yon nanm ki swaf pou Bondye se yon nanm ki pral satisfè. Chache Bondye bonè nan jounen ou e nan chak sikonstans. Li ap satisfè tout swaf nanm ou.", prayer: "Bondye, ou se Bondye mwen. Nanm mwen swaf pou ou. Mwen chache ou bonè e mwen fè ou konfyans pou satisfè m. Amèn.", date: "" },
  { id: "261", verse: "Mwen pa priye pou ou retire yo nan mond lan, men pou ou pwoteje yo kont sa ki mal.", reference: "Jan 17:15", devotional: "Jezi pa priye pou retire nou nan mond lan men pou pwoteje nou ladan l. Ou se yon temwen nan mond sa a, e Bondye pwoteje ou pandan ou la.", prayer: "Papa, pwoteje m kont sa ki mal pandan m nan mond lan. Ede m yon temwen fidèl nan tout kote m ye. Amèn.", date: "" },
  { id: "262", verse: "Ann kouri ak pasyans nan kous ki devan nou.", reference: "Ebre 12:1b", devotional: "Lavi kretyen se pa yon sprint men yon maraton. Li mande pasyans, pèseverans e detèminasyon. Pa lage paske premye pa a se sèlman kòmansman.", prayer: "Senyè, ban m pasyans pou kouri kous ki devan m. Pa kite m lage men kenbe m ap avanse ak detèminasyon. Amèn.", date: "" },
  { id: "263", verse: "Senyè a gen pitye pou moun ki gen krentif pou li, tankou yon papa gen pitye pou pitit li.", reference: "Sòm 103:13b", devotional: "Relasyon ou ak Bondye se yon relasyon papa-pitit plen ak tandres. Li gen pitye pou ou, li konprann frajilite ou e li renmen ou san kondisyon.", prayer: "Papa, mèsi pou tandres ou e pitye ou. Ou se yon bon papa ki renmen pitit li san kondisyon. Amèn.", date: "" },
  { id: "264", verse: "Moun ki renmen lajan p ap janm gen kont lajan, e moun ki renmen richès p ap janm satisfè.", reference: "Eklezyas 5:10", devotional: "Kouri dèyè richès pa pote satisfaksyon. Bondye sèl ka satisfè kè ou. Lè ou mete li an premye, ou dekouvri yon kontantman ki lajan pa ka achte.", prayer: "Senyè, ede m pa renmen lajan men renmen ou sèl. Ou se vrè satisfaksyon kè m, pa richès materyèl. Amèn.", date: "" },
  { id: "265", verse: "Mwen vle konnen Kris e pouvwa rezirèksyon li.", reference: "Filipyen 3:10", devotional: "Konnen Kris se pa sèlman konnen enfòmasyon sou li men gen yon relasyon entim ak li. Lè ou konnen pouvwa rezirèksyon li, sa chanje fason ou viv.", prayer: "Jezi, mwen vle konnen ou plis chak jou. Fè m fè eksperyans pouvwa rezirèksyon ou nan lavi m. Amèn.", date: "" },
  { id: "266", verse: "Mwen wè yon nouvo syèl ak yon nouvo tè, paske premye syèl la ak premye tè a te disparèt.", reference: "Revelasyon 21:1", devotional: "Yon jou tout bagay ap vin tounèf. Bondye ap kreye yon nouvo syèl ak yon nouvo tè kote pa gen soufrans, doulè oswa lanmò. Sa se espwa etènèl ou.", prayer: "Papa, mèsi pou espwa yon nouvo syèl ak yon nouvo tè. Kite espwa sa a soutni m nan jou difisil yo. Amèn.", date: "" },
  { id: "267", verse: "M ap rele non Senyè a ki merite lwanj, e m ap sove anba lènmi m yo.", reference: "Sòm 18:3", devotional: "Rele non Senyè a se pi bon defans nan moman danje. Li merite lwanj e li delivre ou anba tout lènmi. Non li gen pouvwa pou sove e pwoteje.", prayer: "Senyè, mwen rele non ou ki merite lwanj. Sove m anba lènmi m yo e pwoteje m pa pouvwa ou. Amèn.", date: "" },
  { id: "268", verse: "Se konsa, ale fè tout nasyon yo vin disip mwen.", reference: "Matye 28:19", devotional: "Jezi bay yon misyon klè: fè disip nan tout nasyon. Se pa sèlman pou pastè men pou tout kwayan. Ou gen yon wòl nan gaye levanjil la sou tout tè a.", prayer: "Jezi, mwen aksepte misyon ou pou fè disip nan tout nasyon. Itilize m pou gaye levanjil la. Amèn.", date: "" },
  { id: "269", verse: "Mwen menm, mwen se pen lavi a. Moun ki vin jwenn mwen p ap janm grangou.", reference: "Jan 6:35", devotional: "Jezi satisfè swaf ki pi pwofon nan nanm ou. Tankou pen ki nouri kò ou, li nouri nanm ou. Vin jwenn li e ou p ap janm rete grangou espirityèlman.", prayer: "Jezi, ou se pen lavi a. Mwen vin jwenn ou e mwen fè ou konfyans pou nouri nanm mwen. Amèn.", date: "" },
  { id: "270", verse: "Moun ki simen ak dlo nan je yo ap rekòlte ak kè kontan.", reference: "Sòm 126:5", devotional: "Pafwa ou simen nan doulè ak dlo nan je, men Bondye pwomèt yon rekòt ak kè kontan. Pa dekouraje nan sezon difisil yo paske kè kontan ap vini.", prayer: "Senyè, menm lè m ap simen ak dlo nan je, mwen fè ou konfyans pou yon rekòt kè kontan. Amèn.", date: "" },
  { id: "271", verse: "Tout sa ki bèl, tout sa ki bon, tout sa ki merite lwanj, panse sou bagay sa yo.", reference: "Filipyen 4:8", devotional: "Sa ou panse detèmine kijan ou viv. Bondye rele ou pou konsantre panse ou sou sa ki bèl, bon ak merite lwanj. Lè ou fè sa, lapè li ranpli kè ou.", prayer: "Papa, ede m konsantre panse m sou sa ki bèl, bon e ki merite lwanj. Kite panse m onore ou. Amèn.", date: "" },
  { id: "272", verse: "E sou wòch sa a m ap bati legliz mwen, e pòt lanfè p ap genyen sou li.", reference: "Matye 16:18", devotional: "Legliz Kris la bati sou yon fondasyon ki pa ka branle. Okenn fòs ki mal pa ka genyen sou li. Ou se yon pati nan yon bagay ki pisan e ki dire pou tout tan.", prayer: "Jezi, mèsi ke m se yon pati nan legliz ou. Pòt lanfè p ap janm genyen sou nou. Amèn.", date: "" },
  { id: "273", verse: "Bay Seza sa ki pou Seza e bay Bondye sa ki pou Bondye.", reference: "Mak 12:17", devotional: "Jezi anseye ekilib ant responsablite sivik ak devosyon pou Bondye. Bay Bondye premye plas nan lavi ou san neglije responsablite ou nan sosyete a.", prayer: "Senyè, ede m bay ou sa ki pou ou: kè m, lavi m ak tout sa m genyen. Gide m nan tout responsablite m. Amèn.", date: "" },
  { id: "274", verse: "Li pa pè move nouvèl, kè l asire paske li fè Senyè a konfyans.", reference: "Sòm 112:7", devotional: "Moun ki fè Bondye konfyans pa viv nan laperèz move nouvèl. Kè li asire paske li konnen Bondye kenbe tout bagay nan men li. Sa se yon lapè sinatirèl.", prayer: "Papa, ede m pa pè move nouvèl. Kè m asire paske m fè ou konfyans ak tout sa ki ap pase. Amèn.", date: "" },
  { id: "275", verse: "Pawòl sa a vre e merite pou tout moun aksepte li: Kris Jezi te vini nan mond lan pou sove pechè yo.", reference: "1 Timote 1:15", devotional: "Mesaj levanjil la senp men pwofon: Kris te vini pou sove pechè yo. Sa se bon nouvèl la pou tout moun ki konnen yo bezwen yon Sovè.", prayer: "Jezi, mèsi ke ou te vini nan mond lan pou sove m. Mwen se yon pechè ki resevwa gras ou. Amèn.", date: "" },
  { id: "276", verse: "Ann fikse je nou sou Jezi, ki kòmanse e ki fini lafwa nou.", reference: "Ebre 12:2", devotional: "Jezi se kòmansman ak konpletman lafwa ou. Lè ou fikse je ou sou li, tout lòt distaksyon disparèt. Li se egzanp pafè e destinasyon final lafwa ou.", prayer: "Jezi, mwen fikse je m sou ou. Ou kòmanse e ou fini lafwa m. Ede m pa janm pèdi ou nan je m. Amèn.", date: "" },
  { id: "277", verse: "Fè byen, chache jistis, defann moun y ap oprime.", reference: "Ezayi 1:17", devotional: "Bondye rele pèp li pou se defansè moun ki nan bezwen e ki oprime. Lafwa san aksyon sosyal pa konplè. Fè byen e kanpe pou jistis nan tout kote ou ye.", prayer: "Papa, ede m fè byen, chache jistis e defann moun y ap oprime. Kite m yon vwa pou sa ki pa gen vwa. Amèn.", date: "" },
  { id: "278", verse: "Nou se sèl mwen ki sou tè a.", reference: "Matye 5:13", devotional: "Bondye rele ou pou se sèl ki bay gou nan mond sa a. San ou, mond lan ap pèdi gou li. Prezans ou fè yon diferans reyèl nan kominote ou.", prayer: "Senyè, fè m sèl ki bay gou nan mond lan. Kite prezans mwen fè yon diferans reyèl nan kominote m. Amèn.", date: "" },
  { id: "279", verse: "Mwen fè nou sonje pawòl Senyè Jezi a: li plis benediksyon bay pase resevwa.", reference: "Travay 20:35", devotional: "Bay gen yon benediksyon ki pi gwo pase resevwa. Lè ou jenerè, ou reflete karaktè Bondye ki se pi gwo donè. Jenerozite pote kè kontan ki pa gen parèy.", prayer: "Senyè, ede m viv yon lavi jenerè. Li plis benediksyon bay pase resevwa. Fè m jenerè tankou ou. Amèn.", date: "" },
  { id: "280", verse: "Senyè a kanpe bò kote m e li ban m fòs.", reference: "2 Timote 4:17", devotional: "Menm lè tout moun abandone ou, Senyè a ap toujou kanpe bò kote ou. Li ban ou fòs lè ou santi ou pèdi. Ou pa janm poukont ou nan batay ou yo.", prayer: "Senyè, mèsi paske ou kanpe bò kote m e ou ban m fòs. Lè tout moun ale, ou rete la. Amèn.", date: "" },
  { id: "281", verse: "M ap di Senyè a: Ou se refij mwen ak fòtrès mwen, Bondye mwen nan ki mwen fè konfyans.", reference: "Sòm 91:2", devotional: "Deklare ak bouch ou ke Bondye se refij ou ak fòtrès ou. Pawòl ou gen pouvwa. Lè ou di sa ou kwè sou Bondye, lafwa ou ranfòse.", prayer: "Senyè, ou se refij mwen ak fòtrès mwen. Bondye mwen, mwen fè ou konfyans nan tout bagay. Amèn.", date: "" },
  { id: "282", verse: "Lè Lespri Bondye a rete nan nou, li ba nou pouvwa, lanmou ak metriz.", reference: "2 Timote 1:7b", devotional: "Lespri Bondye nan ou se yon Lespri pouvwa, lanmou ak metriz. Pa viv nan laperèz men nan otorite li ba ou. Ou ekipe pou tout sa Bondye rele ou fè.", prayer: "Sentespri, mèsi pou pouvwa, lanmou ak metriz ou ban m. Ede m mache nan otorite ou chak jou. Amèn.", date: "" },
  { id: "283", verse: "Jezi di: Kite timoun yo vin jwenn mwen. Pa anpeche yo, paske wayòm syèl la se pou moun ki tankou yo.", reference: "Matye 19:14", devotional: "Jezi gen yon kote espesyal nan kè li pou timoun ak pou tout moun ki gen yon kè senp tankou timoun. Vin bò kote li ak imilite ak konfyans yon timoun.", prayer: "Jezi, ban m yon kè senp ak konfyan tankou yon timoun. Mwen vin jwenn ou ak imilite e lanmou. Amèn.", date: "" },
  { id: "284", verse: "Bondye p ap kite nou tante plis pase sa nou ka sipòte; men ak tantasyon an li bay yon pòt sòti tou.", reference: "1 Korentyen 10:13", devotional: "Bondye konnen limit ou e li fidèl pou pa kite tantasyon depase sa ou ka sipòte. Li toujou bay yon pòt sòti. Chache li e ou ap jwenn li.", prayer: "Papa, mèsi ke ou fidèl nan chak tantasyon. Montre m pòt sòti a e ban m fòs pou pase ladan l. Amèn.", date: "" },
  { id: "285", verse: "Ala fò pouvwa Bondye ye nan nou ki kwè!", reference: "Efezyen 1:19", devotional: "Menm pouvwa ki te leve Kris nan lanmò ap travay nan ou. Pouvwa Bondye nan kwayan yo imenseman gran. Ou gen aksè ak pouvwa sinatirèl chak jou.", prayer: "Papa, louvri je m pou wè gwo pouvwa ou ki travay nan mwen. Kite m mache nan pouvwa rezirèksyon ou. Amèn.", date: "" },
  { id: "286", verse: "Senyè a ap gide ou toutan. Li ap satisfè bezwen ou nan tè sèk.", reference: "Ezayi 58:11", devotional: "Gidaj Bondye pa sèlman pou pafwa men pou tout tan. Li gide ou san rete e li satisfè bezwen ou menm nan kote ki pi dezole nan lavi a.", prayer: "Senyè, gide m toutan. Satisfè bezwen m menm nan tè sèk kote tout bagay parèt difisil. Amèn.", date: "" },
  { id: "287", verse: "Fè tout bagay pou glwa Bondye.", reference: "1 Korentyen 10:31", devotional: "Tout sa ou fè, kit li gwo oswa piti, ka se yon aksyon adorasyon. Lè ou fè tout bagay pou glwa Bondye, menm aktivite chak jou vin gen siyifikasyon etènèl.", prayer: "Papa, ede m fè tout bagay pou glwa ou. Kite chak aksyon m se yon fason pou adore ou. Amèn.", date: "" },
  { id: "288", verse: "Li di yo: Sa ki enposib pou moun posib pou Bondye.", reference: "Lik 18:27", devotional: "Sa ki parèt enposib nan je imen posib pou Bondye. Pa gen limit nan sa li ka fè. Lè ou fè fas ak enposib, sonje ou gen yon Bondye pou ki anyen pa enposib.", prayer: "Papa, sa ki enposib pou mwen posib pou ou. Mwen fè ou konfyans ak sitiyasyon ki parèt enposib nan lavi m. Amèn.", date: "" },
  { id: "289", verse: "Mwen sèten ke ni lanmò, ni lavi, ni zanj, ni chèf, ni sa ki la kounye a, ni sa ki gen pou vini, pa ka separe nou ak lanmou Bondye.", reference: "Women 8:38-39", devotional: "Pa gen okenn fòs nan linivè ki ka separe ou ak lanmou Bondye nan Kris. Ni lanmò, ni lavi, ni okenn kreyati pa gen pouvwa sa a. Lanmou li se yon garanti etènèl.", prayer: "Papa, mèsi ke anyen pa ka separe m ak lanmou ou nan Kris Jezi. Lanmou ou etènèl e irevokab. Amèn.", date: "" },
  { id: "290", verse: "Jan yon papa gen konpasyon pou pitit li, se konsa Senyè a gen konpasyon pou moun ki gen krentif pou li.", reference: "Sòm 103:13c", devotional: "Konpasyon Bondye pou ou tankou yon papa ki gen pitye pou pitit li. Li konprann frajilite ou e li reponn ak dousè e lanmou, pa ak kondanasyon.", prayer: "Papa, mèsi pou konpasyon ou. Ou konprann frajilite m e ou reponn ak lanmou olye kondanasyon. Amèn.", date: "" },
  { id: "291", verse: "Mwen se menm yè, jodi a ak pou tout tan.", reference: "Ebre 13:8", devotional: "Jezi pa chanje. Li menm yè, jodi a e pou tout tan. Nan yon mond ki toujou ap chanje, ou gen yon Sovè ki rete menm jan an. Sa se fondasyon konfyans ou.", prayer: "Jezi, mèsi ke ou pa janm chanje. Ou menm yè, jodi a ak pou tout tan. Konfyans mwen nan ou solid. Amèn.", date: "" },
  { id: "292", verse: "Mwen pral di kichòy sou ou: ou merite konfyans. Nan ti kras bagay ou te fidèl.", reference: "Matye 25:23", devotional: "Bondye wè fidelite ou nan ti detay yo. Li pa mande pèfòmans spektakèl men fidelite nan sa li ba ou. Kontinye fidèl nan ti bagay yo e li ap ba ou plis.", prayer: "Senyè, ede m vin fidèl nan ti bagay yo. Mwen vle ke ou di: ou merite konfyans. Amèn.", date: "" },
  { id: "293", verse: "Men se gras a Bondye mwen se sa m ye a, e gras li anvè mwen pa te vid.", reference: "1 Korentyen 15:10", devotional: "Tout sa ou ye se pa gras Bondye. Gras li pa rete vid nan lavi ou men li pwodui fwi. Aksepte gras li e kite li travay nan ou pou pwodui bon bagay.", prayer: "Papa, mèsi ke mwen se sa m ye pa gras ou. Kite gras ou pwodui bon fwi nan lavi m. Amèn.", date: "" },
  { id: "294", verse: "Leve kanpe, briye, paske limyè ou rive e glwa Senyè a klere sou ou.", reference: "Ezayi 60:1", devotional: "Bondye rele ou pou leve e briye. Limyè li rive sou ou e glwa li kouvri ou. Ou pa fèt pou rete nan fènwa men pou briye ak limyè Bondye.", prayer: "Senyè, mwen leve e mwen briye paske limyè ou rive sou mwen. Kite glwa ou klere nan lavi m. Amèn.", date: "" },
  { id: "295", verse: "Fè aksyon de gras nan tout bagay, paske se volonte Bondye nan Kris Jezi pou nou.", reference: "1 Tesalonisyen 5:18b", devotional: "Rekonesans se volonte Bondye pou ou. Pa sèlman nan bon moman men nan tout bagay. Lè ou remèsye li nan tout sikonstans, sa chanje pèspektiv ou e rapwoche ou bò kote li.", prayer: "Papa, mwen fè ou aksyon de gras nan tout bagay paske se volonte ou. Ede m gen yon kè rekonesan. Amèn.", date: "" },
  { id: "296", verse: "Avan mòn yo te fèt, avan ou te bay tè a ak mond lan fòm, depi tout tan jouk tout tan, se ou ki Bondye.", reference: "Sòm 90:2", devotional: "Bondye pa gen kòmansman ni fen. Li te la anvan tout bagay e li ap la apre tout bagay. Fè konfyans nan yon Bondye etènèl ki kenbe tout tan nan men li.", prayer: "Bondye etènèl, ou te la anvan tout bagay e ou ap la pou tout tan. Mwen adore ou e mwen fè ou konfyans. Amèn.", date: "" },
  { id: "297", verse: "Se pou nou gen bon konpòtman pami lòt nasyon yo, pou lè yo akize nou de fè mal, yo ka wè bon aksyon nou e glorifye Bondye.", reference: "1 Pyè 2:12", devotional: "Fason ou viv se yon mesaj pou moun ki pa konnen Bondye. Lè yo wè bon aksyon ou, menm moun ki kont ou ka vin glorifye Bondye. Viv yon lavi ki pale fò.", prayer: "Senyè, kite bon konpòtman m pale de ou a moun ki pa konnen ou. Ede m viv yon lavi ki glorifye ou. Amèn.", date: "" },
  { id: "298", verse: "M ap chante pou Senyè a tout lavi m. M ap fè lwanj Bondye mwen pandan m vivan.", reference: "Sòm 104:33", devotional: "Lwanj se pa sèlman pou dimanch men pou chak jou nan lavi ou. Fè lwanj Bondye ak tout lavi ou, nan chak sezon e nan chak sikonstans.", prayer: "Senyè, mwen chante pou ou tout lavi m. M ap fè lwanj ou pandan m gen souf nan kò m. Amèn.", date: "" },
  { id: "299", verse: "Se pou nou gen menm santiman pou youn lòt. Pa mete nan tèt nou pou fè gwo bagay, men dakò desann kote moun ki enb yo.", reference: "Women 12:16", devotional: "Imilite ak inite mache ansanm nan kominote kretyen an. Pa chache grandè men desann kote moun ki enb. Sa se chemen Kris la e sa se chemen benediksyon.", prayer: "Papa, ban m imilite pou desann kote moun ki enb yo. Ede m gen menm santiman pou tout moun. Amèn.", date: "" },
  { id: "300", verse: "Men glwa Bondye se kache yon bagay, e glwa wa yo se chache sa ki kache.", reference: "Pwovèb 25:2", devotional: "Bondye kache trezò nan Pawòl li pou moun ki chache yo ak dilijans. Lè ou fouye nan verite li, ou dekouvri richès ki transfòme lavi ou.", prayer: "Papa, ban m swaf pou fouye nan Pawòl ou. Ede m dekouvri trezò ou kache pou moun ki chache ou. Amèn.", date: "" },
  { id: "301", verse: "Mwen vini pou mouton yo ka gen lavi, pou yo ka genyen li an abondans.", reference: "Jan 10:10", devotional: "Jezi pa t vini pou bay ou yon lavi mediokr men yon lavi abondan. Li vle ou gen plis pase ou bezwen nan chak domèn: lapè, kè kontan, lanmou ak siyifikasyon.", prayer: "Jezi, mèsi ke ou vini pou m gen lavi an abondans. Ede m viv totalman nan sa ou ofri m. Amèn.", date: "" },
  { id: "302", verse: "Mache nan limyè jan li menm li nan limyè.", reference: "1 Jan 1:7", devotional: "Mache nan limyè vle di viv ak onestete, transparans ak pirite. Lè ou viv nan limyè Bondye, peche pa gen kote pou kache e kominyon ak li rete fò.", prayer: "Senyè, ede m mache nan limyè jan ou nan limyè. Kite onestete ak pirite gide lavi m. Amèn.", date: "" },
  { id: "303", verse: "Gen tan pou tout bagay, yon sezon pou chak aktivite anba syèl la.", reference: "Eklezyas 3:1", devotional: "Bondye gen yon sezon pou tout bagay nan lavi ou. Pa fòse bagay avan lè yo men fè konfyans nan sajès li ki konnen bon moman pou chak bagay.", prayer: "Papa, ede m aksepte sezon m ladan l ye a. Ou gen yon tan pou tout bagay e ou konnen sa ki pi bon pou mwen. Amèn.", date: "" },
  { id: "304", verse: "M ap beni Senyè a nan tout tan; lwanj li ap toujou nan bouch mwen.", reference: "Sòm 34:1", devotional: "Lwanj se pa yon repons oksyonèl men yon desizyon. Beni Senyè a nan tout tan, pa sèlman lè bagay ap byen mache. Kite lwanj rete nan bouch ou toutan.", prayer: "Senyè, mwen beni ou nan tout tan. Lwanj ou ap toujou nan bouch mwen, nan bon e move moman. Amèn.", date: "" },
  { id: "305", verse: "Lakwa pou moun k ap peri se foli, men pou nou menm k ap sove, se pouvwa Bondye.", reference: "1 Korentyen 1:18", devotional: "Mesaj kwa a ka parèt fou pou kèk moun, men pou nou ki kwè, se pouvwa Bondye ki sove. Pa wont mesaj la paske li gen pouvwa pou chanje lavi.", prayer: "Papa, mèsi pou pouvwa kwa a. Li se pouvwa delivrans ou pou mwen. Mwen pa wont mesaj la. Amèn.", date: "" },
  { id: "306", verse: "Se poutèt sa tou, Bondye leve l wo anpil e li ba l yon non ki pi wo pase tout lòt non.", reference: "Filipyen 2:9", devotional: "Bondye te leve Jezi nan pozisyon ki pi wo nan linivè. Non li anwo tout lòt non. Yon jou tout jenou ap bese e tout lang ap konfese ke li se Senyè.", prayer: "Senyè Jezi, non ou pi wo pase tout lòt non. Mwen bese devan ou ak onè e lwanj. Amèn.", date: "" },
  { id: "307", verse: "An n pa fatige fè sa ki bon, paske nan bon moman, n ap rekòlte si nou pa lage.", reference: "Galat 6:9b", devotional: "Lè ou santi ou fatige fè byen, sonje rekòt la ap vini. Bondye pa janm bliye efò ou. Pèsevere ak detèminasyon paske rekonpans la sèten.", prayer: "Papa, ban m fòs pou pa fatige fè sa ki bon. Mwen fè ou konfyans pou yon rekòt nan bon moman. Amèn.", date: "" },
  { id: "308", verse: "Se pa moun ki fè traka l ap genyen pitye, men pou moun li konpatisan.", reference: "Sòm 116:5", devotional: "Bondye gen pitye ak konpasyon pou ou san kondisyon. Li pa gade sou merite ou men sou bezwen ou. Konpasyon li disponib pou ou jodi a.", prayer: "Senyè, mèsi pou pitye ak konpasyon ou. Ou pa gade sou merite m men sou bezwen m. Amèn.", date: "" },
  { id: "309", verse: "M ap mete lwa m nan kè yo e m ap ekri li nan lespri yo.", reference: "Jeremi 31:33", devotional: "Bondye pa sèlman bay règ ekstèn men li ekri lwa li nan kè ou. Li chanje ou de anndan pou ou ka viv pou li natirèlman, pa pa obligasyon men pa lanmou.", prayer: "Papa, ekri lwa ou nan kè m e nan lespri m. Kite obeyisans mwen soti nan lanmou, pa nan obligasyon. Amèn.", date: "" },
  { id: "310", verse: "Mwen pa mande pou ou retire yo nan mond lan men pou ou veye sou yo kont mal la.", reference: "Jan 17:15b", devotional: "Jezi priye pou pwoteksyon ou nan mond lan, pa retrè ou nan li. Ou se yon anbsadè Kris nan mond sa a, pwoteje pa lapriyè Sovè a li menm.", prayer: "Jezi, mèsi pou lapriyè ou pou pwoteksyon m. Ede m yon bon anbsadè nan mond sa a. Amèn.", date: "" },
  { id: "311", verse: "An nou renmen youn lòt, paske lanmou soti nan Bondye.", reference: "1 Jan 4:7", devotional: "Lanmou se pa sèlman yon santiman men yon refleksyon Bondye nan nou. Lè nou renmen youn lòt, nou montre ke nou konnen Bondye paske li se sous tout lanmou.", prayer: "Papa, ede m renmen youn lòt paske lanmou soti nan ou. Kite lanmou ou koule atravè mwen. Amèn.", date: "" },
  { id: "312", verse: "Seyè, ou sonde m e ou konnen m. Ou konnen lè m chita e lè m kanpe.", reference: "Sòm 139:1-2", devotional: "Bondye konnen ou entimman e totalman. Li wè tout sa ou fè e li konprann tout sa ou panse. Ou pa ka kache anyen nan men li, men sa pa fè li renmen ou mwens.", prayer: "Senyè, ou konnen m entimman. Menm sa m kache, ou wè li. Mèsi ke ou renmen m kanmenm. Amèn.", date: "" },
  { id: "313", verse: "M ap rakontre bonte Senyè a. Mwen p ap bliye tout byenfè li yo.", reference: "Sòm 103:2", devotional: "Pa janm bliye byenfè Bondye nan lavi ou. Lè ou rakontre bonte li, sa ranfòse lafwa ou e ba ou fòs pou avanse. Rekonesans se yon zam pisan.", prayer: "Senyè, mwen fè lwanj ou pou tout byenfè ou. Mwen p ap bliye bonte ou nan lavi m. Amèn.", date: "" },
  { id: "314", verse: "Se pa mwen ki chwazi nou, se mwen ki chwazi nou e ki etabli nou pou nou ale pote fwi.", reference: "Jan 15:16", devotional: "Bondye chwazi ou ak entansyon. Ou pa te jwenn li pa aza men li te chwazi ou espesyalman pou pote fwi ki dire. Viv nan objektif sa a ak detèminasyon.", prayer: "Jezi, mèsi ke ou chwazi m e etabli m. Ede m pote fwi ki dire pou glwa ou. Amèn.", date: "" },
  { id: "315", verse: "Pi gwo kòmandman an se renmen Senyè a, Bondye ou la, ak tout kè ou, ak tout nanm ou, ak tout fòs ou, ak tout panse ou.", reference: "Lik 10:27", devotional: "Renmen Bondye totalman se pi gwo apèl nan lavi a. Ak tout kè ou, nanm ou, fòs ou ak panse ou. Pa gen yon pati nan ou ki ta dwe rete deyò lanmou sa a.", prayer: "Papa, mwen renmen ou ak tout kè m, nanm mwen, fòs mwen ak panse m. Pa kite okenn pati nan mwen rete deyò. Amèn.", date: "" },
  { id: "316", verse: "Mwen menm mwen plen kè kontan e mwen gen yon gwo kè kontan nan Senyè a.", reference: "Filipyen 4:10", devotional: "Kè kontan nan Senyè a pa depann de sikonstans men de relasyon ou ak li. Pol te jwenn kè kontan menm nan prizon. Ou ka jwenn kè kontan nan Senyè a nenpòt kote ou ye.", prayer: "Senyè, ranpli m ak kè kontan nan ou. Pa gen sikonstans ki ka vòlè kè kontan m nan ou. Amèn.", date: "" },
  { id: "317", verse: "Se limyè ki klere nan fènwa, e fènwa pa t ka genyen l.", reference: "Jan 1:5", devotional: "Limyè Bondye pi pisan pase nenpòt fènwa. Pa gen fènwa ki ka genyen sou limyè li. Nenpòt sitiyasyon ki parèt nwa, limyè li ka klere ladan l.", prayer: "Senyè, ou se limyè ki klere nan fènwa. Pa gen fènwa ki ka genyen sou ou. Klere limyè ou nan lavi m. Amèn.", date: "" },
  { id: "318", verse: "Li pini pitit li renmen yo, li bat yo tout li resevwa kòm pitit li.", reference: "Ebre 12:6", devotional: "Disiplin Bondye se yon siy lanmou, pa rejè. Lè li korije ou, se paske ou se pitit li e li vle pi bon pou ou. Aksepte disiplin li ak rekonesans.", prayer: "Papa, mèsi ke disiplin ou se prèv lanmou ou. Ede m aksepte koreksyon ou ak imilite e rekonesans. Amèn.", date: "" },
  { id: "319", verse: "Pa gen laperèz nan lanmou. Men, lanmou ki pafè chase laperèz.", reference: "1 Jan 4:18", devotional: "Lanmou pafè Bondye chase tout laperèz. Lè ou konnen vrèman konbyen li renmen ou, laperèz pa gen kote pou rete. Kite lanmou li chase tout laperèz nan kè ou.", prayer: "Papa, kite lanmou pafè ou chase tout laperèz nan kè m. Lè m konnen ou renmen m, mwen pa pè anyen. Amèn.", date: "" },
  { id: "320", verse: "Mwen te fè ou vin yon limyè pou nasyon yo, pou delivrans mwen rive nan bout latè.", reference: "Ezayi 49:6", devotional: "Limyè Bondye pa pou yon sèl nasyon men pou tout tè a. Li vle tout moun konnen delivrans li. Ou gen yon wòl nan pote limyè sa a kote ou ye.", prayer: "Senyè, kite m yon limyè pou nasyon yo. Itilize m pou pote delivrans ou nan bout latè. Amèn.", date: "" },
  { id: "321", verse: "Mwen te vin chache e sove sa ki te pèdi.", reference: "Lik 19:10b", devotional: "Misyon Jezi te klè: chache e sove sa ki te pèdi. Si ou santi ou pèdi jodi a, li ap chache ou. Si ou deja jwenn, ede lòt moun jwenn li tou.", prayer: "Jezi, mèsi ke ou te vin chache m lè m te pèdi. Kounye a ede m ede lòt moun jwenn ou tou. Amèn.", date: "" },
  { id: "322", verse: "Koute sa mwen mande nou: renmen lènmi nou yo, fè byen pou moun ki rayi nou.", reference: "Lik 6:27", devotional: "Renmen lènmi ou se youn nan kòmandman ki pi difisil Jezi te bay. Men se lanmou sa a ki diferansye disip Kris de rès mond lan. Se yon lanmou sinatirèl.", prayer: "Jezi, ban m gras pou renmen lènmi m yo. Se sèlman ak pouvwa ou mwen ka fè sa. Amèn.", date: "" },
  { id: "323", verse: "Tan Senyè a vini, li pwòch.", reference: "Jak 5:8", devotional: "Retou Senyè a pwòch. Viv chak jou ak konsyans sa a. Pa pèdi tan nan bagay ki pa gen valè etènèl men konsantre sou sa ki enpòtan pou Bondye.", prayer: "Senyè, ede m viv chak jou kòmsi ou ka retounen nenpòt lè. Kite konsyans sa a gide chwa m yo. Amèn.", date: "" },
  { id: "324", verse: "Pou Bondye tout bagay posib.", reference: "Matye 19:26", devotional: "Sèl limit ki egziste se limit imen. Pou Bondye pa gen anyen ki enposib. Nenpòt defi ou ap fè fas, sonje Bondye pa gen limit nan sa li ka fè.", prayer: "Papa, mwen kwè ke tout bagay posib pou ou. Mwen mete defi m yo nan men ou ki pa gen limit. Amèn.", date: "" },
  { id: "325", verse: "M ap ba yo yon sèl kè e m ap mete yon nouvo lespri nan yo.", reference: "Ezekyèl 11:19", devotional: "Bondye travay nan inite kè ak lespri. Li retire kè ki di e li mete yon lespri nouvo nan ou. Transfòmasyon sa a se travay Bondye, pa efò imen.", prayer: "Bondye, ban m yon sèl kè ak yon nouvo lespri. Retire sa ki di nan mwen e mete sa ki dous. Amèn.", date: "" },
  { id: "326", verse: "Se konsa Kris te mouri yon fwa pou tout pou peche, li menm ki jis pou moun ki pa jis, pou mennen nou bò kote Bondye.", reference: "1 Pyè 3:18", devotional: "Kris te mouri yon sèl fwa e pou tout tan pou peche. Sakrifis li konplè e sifi. Pa gen anyen pou ajoute; sèlman resevwa ak lafwa sa li deja fè.", prayer: "Jezi, mèsi pou sakrifis ou ki konplè e sifi. Ou te mouri pou m ka vin bò kote Bondye. Amèn.", date: "" },
  { id: "327", verse: "Mwen mande pou ou gen fòs nan moun anndan ou pa Lespri li.", reference: "Efezyen 3:16", devotional: "Fòs espirityèl pa vini pa efò imen men pa Lespri Bondye ki travay anndan ou. Li ranfòse ou de anndan, kote ki pi enpòtan.", prayer: "Papa, ranfòse moun anndan m pa Lespri ou. Kite fòs espirityèl grandi nan mwen chak jou. Amèn.", date: "" },
  { id: "328", verse: "Moun ki gen bon konprann jwenn sa ki bon. Moun ki mete konfyans yo nan Senyè a beni.", reference: "Pwovèb 16:20", devotional: "Bon konprann mennen nan bon rezilta e konfyans nan Bondye mennen nan benediksyon. De a mache ansanm: sajès nan desizyon e konfyans nan Bondye.", prayer: "Senyè, ban m bon konprann e ede m mete konfyans mwen nan ou. Se konsa m ap jwenn sa ki bon. Amèn.", date: "" },
  { id: "329", verse: "Senyè a ap goumen batay la pou nou. Nou menm rete trankil.", reference: "Egzòd 14:14c", devotional: "Genyen batay kote Bondye di ou rete trankil e kite li fè travay la. Fè li konfyans ase pou rete sou kote e kite li montre pouvwa li.", prayer: "Papa, mwen rete trankil e mwen kite ou goumen batay sa a pou mwen. Pouvwa ou pi gran pase tout. Amèn.", date: "" },
  { id: "330", verse: "Benediksyon pou moun ki fè dèy, paske y a jwenn konsolasyon.", reference: "Matye 5:4", devotional: "Nan moman tristès ak doulè, Bondye pwomèt konsolasyon. Li pa inyore doulè ou men li vini kòm Konsolatè. Kite li konsole kè ou nan moman difisil yo.", prayer: "Papa, konsole m nan doulè m. Ou se Bondye tout konsolasyon e ou pwòch moun ki gen kè brize. Amèn.", date: "" },
  { id: "331", verse: "Lè ou pase nan dlo yo, m ap avèk ou. Lè ou travèse rivyè a, li p ap bwaye ou.", reference: "Ezayi 43:2b", devotional: "Bondye pa pwomèt ou p ap gen pwoblèm, men li pwomèt prezans li nan mitan yo. Dlo a ka monte wo men ou p ap neye paske li la avèk ou.", prayer: "Senyè, lè dlo yo monte wo, mwen konnen ou avèk mwen. Mwen p ap bwaye paske ou kenbe m. Amèn.", date: "" },
  { id: "332", verse: "Bondye mwen an gen tout sa ki nesesè pou li satisfè tout bezwen nou, dapre richès glwa li nan Kris Jezi.", reference: "Filipyen 4:19b", devotional: "Resous Bondye pa janm fini. Li gen tout sa ki nesesè pou bay ou sa ou bezwen. Pa enkyete pou demen paske Bondye gen pwovizyon ki pare pou ou.", prayer: "Papa, mwen fè ou konfyans paske ou gen tout sa ki nesesè pou satisfè bezwen m yo. Amèn.", date: "" },
  { id: "333", verse: "Mwen te pran chenn ou yo e mwen te kase yo, e mwen fè ou mache ak tèt wo.", reference: "Levitik 26:13", devotional: "Bondye se Liberatè a. Li pran chenn ki te kenbe ou e li kase yo. Li fè ou mache lib ak tèt wo. Aksepte libète li bay ou e pa retounen nan esklavaj.", prayer: "Senyè, mèsi paske ou kase chenn mwen yo. Mwen mache lib ak tèt wo gras a pouvwa ou. Amèn.", date: "" },
  { id: "334", verse: "Pran joug mwen sou nou e aprann nan men m, paske mwen dou e enb nan kè.", reference: "Matye 11:29", devotional: "Joug Jezi lejè paske li mache avèk ou. Li pa mande ou pote chay la poukont ou. Lè ou aprann nan men li, ou dekouvri repo pou nanm ou.", prayer: "Jezi, mwen pran joug ou ki lejè. Anseye m dousè ak imilite. Mwen jwenn repo nan men ou. Amèn.", date: "" },
  { id: "335", verse: "Wi, nan tout bagay sa yo nou genyen laviktwa nèt gras a Sila ki renmen nou an.", reference: "Women 8:37", devotional: "Ou pa sèlman genyen, ou gen laviktwa nèt gras a Kris ki renmen ou. Pa gen batay ki ka bat ou finalman paske lanmou Kris la garanti viktwa ou.", prayer: "Senyè, mwen genyen laviktwa nèt gras a lanmou ou. Pa gen anyen ki ka bat mwen finalman nan ou. Amèn.", date: "" },
  { id: "336", verse: "Moun ki mache ak moun ki gen bon sans ap vin gen bon sans tou, men zanmi moun ki sòt ap gen pwoblèm.", reference: "Pwovèb 13:20", devotional: "Moun ou chwazi pou zanmi gen yon gwo enfliyans sou lavi ou. Mache ak moun ki gen bon sans e sajès paske zanmitay fòme karaktè ou.", prayer: "Papa, ede m chwazi zanmi ki gen bon sans. Kite relasyon m yo fòme m vin pli bon. Amèn.", date: "" },
  { id: "337", verse: "Kounye a, nan Kris Jezi, nou menm ki te lwen, yo fè nou vin toupre pa san Kris la.", reference: "Efezyen 2:13", devotional: "Pa gen enpòtans ki distans ou te ye de Bondye, san Kris la fè ou vin toupre. Ou pa lwen ankò men toupre, aksepte e enbrase nan lanmou li.", prayer: "Jezi, mèsi ke san ou te fè m vin toupre Bondye. Mwen pa lwen ankò men aksepte nan lanmou ou. Amèn.", date: "" },
  { id: "338", verse: "Senyè a di: Mwen pral gide ou e montre ou chemen pou ou pran.", reference: "Sòm 32:8b", devotional: "Bondye pwomèt gidaj pèsonèl pou lavi ou. Li pa sèlman voye ou men li akonpanye ou. Li montre ou chemen an e li mache avèk ou sou li.", prayer: "Senyè, gide m e montre m chemen pou m pran. Mèsi ke ou mache avèk mwen sou chemen an. Amèn.", date: "" },
  { id: "339", verse: "Nou gen espwa sa a kòm yon lank pou nanm nou, ki solid e ki asire.", reference: "Ebre 6:19", devotional: "Espwa nan Kris se tankou yon lank ki kenbe nanm ou fèm nan mitan tanpèt yo. Li solid e asire paske li baze sou pwomès Bondye ki pa ka manti.", prayer: "Senyè, espwa m nan ou se lank pou nanm mwen. Li solid, li asire e li pa ka branle. Amèn.", date: "" },
  { id: "340", verse: "Bondye mwen ap leve limyè li sou figi m e li ap ban m favè li.", reference: "Sòm 67:1", devotional: "Lè Bondye leve limyè li sou ou, favè li vin sou ou. Sa se pa sèlman pou ou men pou tout moun ki wè limyè li nan lavi ou.", prayer: "Bondye, leve limyè ou sou figi m e ban m favè ou. Kite benediksyon ou sou mwen beni lòt moun tou. Amèn.", date: "" },
  { id: "341", verse: "An nou peye byen pou mal, e benediksyon pou madichon.", reference: "1 Pyè 3:9", devotional: "Repons Kris la a mal se toujou byen. Lè ou peye byen pou mal, ou brize sik vyolans e ou demontre pouvwa lanmou Bondye nan mond lan.", prayer: "Senyè, ban m fòs pou peye byen pou mal. Kite repons mwen toujou reflete lanmou Kris. Amèn.", date: "" },
  { id: "342", verse: "Se konsa tout moun va konnen ke nou se disip mwen, si nou gen lanmou youn pou lòt.", reference: "Jan 13:35", devotional: "Lanmou se mak fabrik disip Kris yo. Se pa konesans, ni kapasite, men lanmou ki fè moun rekonèt ou kòm yon moun ki swiv Jezi. Renmen youn lòt fèvaman.", prayer: "Jezi, kite lanmou m pou frè ak sè m yo montre mond lan ke m se disip ou. Amèn.", date: "" },
  { id: "343", verse: "Mwen fè ou konnen yon gwo kè kontan ki pou tout pèp la.", reference: "Lik 2:10", devotional: "Mesaj Nwèl la se yon gwo kè kontan pou tout pèp la. Kè kontan sa a se pa pou kèk moun men pou tout moun ki resevwa li ak lafwa.", prayer: "Papa, mèsi pou gwo kè kontan ou bay tout pèp la. Kite kè kontan sa a ranpli kè m jodi a. Amèn.", date: "" },
  { id: "344", verse: "Mwen rete nan lanmou li tankou yon pitit ki rete nan bra papa li.", reference: "Sòm 131:2", devotional: "Pafwa pi bon pozisyon se rete kalm nan bra Papa ou. Tankou yon timoun ki an pè nan bra papa li, rete nan lanmou Bondye e kite li pran swen ou.", prayer: "Papa, mwen rete kalm nan bra ou. Tankou yon pitit ki an sekirite, mwen repoze nan lanmou ou. Amèn.", date: "" },
  { id: "345", verse: "Kounye a, Senyè a se Lespri a, e kote Lespri Senyè a ye, gen libète.", reference: "2 Korentyen 3:17", devotional: "Lespri Senyè a pote vrè libète. Pa sèlman libète nan peche men libète pou viv pou Bondye ak kè kontan. Kote Lespri li ye, chenn yo kase.", prayer: "Sentespri, pote libète nan lavi m. Kote ou ye, chenn yo kase e mwen lib. Amèn.", date: "" },
  { id: "346", verse: "Mwen fè glwa pou feblès mwen, pou pouvwa Kris ka rete sou mwen.", reference: "2 Korentyen 12:9b", devotional: "Feblès ou pa yon wont men yon opòtinite pou pouvwa Kris briye. Lè ou aksepte feblès ou, ou ouvri pòt pou fòs Bondye travay nan ou.", prayer: "Senyè, mwen aksepte feblès mwen paske nan li pouvwa ou parèt. Kite fòs ou travay nan mwen. Amèn.", date: "" },
  { id: "347", verse: "Mwen te pale ak tè a e ak syèl la, e Senyè a te reponn mwen avèk dife.", reference: "1 Wa 18:38", devotional: "Lè Eli te priye, Bondye te reponn ak dife. Bondye toujou reponn lapriyè ki soti nan yon kè sensè. Li se Bondye vivan ki aji nan lavi moun li yo.", prayer: "Bondye vivan, reponn lapriyè m ak pouvwa ou. Montre ou se Bondye ki aji nan lavi moun li yo. Amèn.", date: "" },
  { id: "348", verse: "Men benediksyon pou moun ki pa wè men ki kwè.", reference: "Jan 20:29", devotional: "Jezi pwononse yon benediksyon espesyal sou moun ki kwè san yo pa wè. Lafwa ou pa bezwen prèv vizib pou rete fèm. Kwè e ou beni.", prayer: "Jezi, mwen kwè san m pa wè. Mwen resevwa benediksyon ou pou moun ki gen lafwa. Amèn.", date: "" },
  { id: "349", verse: "Senyè a te di Abraram: Mwen pral beni ou e fè non ou vin gran.", reference: "Jenèz 12:2", devotional: "Menm jan Bondye te beni Abraram, li vle beni ou tou. Benediksyon li pa sèlman pou ou men pou ou ka vin yon benediksyon pou lòt moun.", prayer: "Papa, beni m e fè m vin yon benediksyon pou lòt moun. Kite benediksyon ou sou mwen gaye toupatou. Amèn.", date: "" },
  { id: "350", verse: "Lanmou pa fè sa ki mal a pwochen li. Donk lanmou se akonplisman lalwa.", reference: "Women 13:10", devotional: "Lanmou rezime tout lalwa Bondye. Lè ou renmen pwochen ou jan ou dwe, ou akonpli lalwa Bondye. Lanmou se fondman tout kòmandman.", prayer: "Papa, ede m renmen pwochen m jan ou vle. Lanmou se akonplisman lalwa ou e mwen vle viv ladan l. Amèn.", date: "" },
  { id: "351", verse: "E Pawòl la te vin tounen moun, e li te vin rete pami nou.", reference: "Jan 1:14", devotional: "Bondye pa rete lwen; li te vin tounen moun e li te vin rete pami nou. Nan Jezi, nou wè Bondye fas a fas. Li konprann lavi imen paske li te viv li.", prayer: "Jezi, mèsi ke ou te vin tounen moun pou rete pami nou. Ou konprann lavi m paske ou te viv li. Amèn.", date: "" },
  { id: "352", verse: "Mwen gen tan pou tout bagay, men tout bagay pa itil.", reference: "1 Korentyen 6:12", devotional: "Libète nan Kris pa vle di fè nenpòt bagay men chwazi fè sa ki itil e ki edifye. Sajès se konnen ki bagay pou chwazi pami tout sa ki disponib.", prayer: "Senyè, ban m sajès pou chwazi sa ki itil e ki edifye. Kite libète m nan ou gide nan bon chwa. Amèn.", date: "" },
  { id: "353", verse: "Li fè dife a soti nan syèl la e li manje ofrann nan.", reference: "2 Kwonik 7:1", devotional: "Lè Bondye reponn, li reponn ak pouvwa. Dife li konsime ofrann lan totalman. Lè ou bay li tout sa ou genyen, li aksepte ak fòs sinatirèl.", prayer: "Papa, mwen ofri tout sa m genyen ba ou. Aksepte ofrann mwen e reponn ak pouvwa ou. Amèn.", date: "" },
  { id: "354", verse: "Beni yo ki pèsekite nou; beni e pa madichonnen.", reference: "Women 12:14", devotional: "Beni moun ki fè ou mal se youn nan pi gwo temwayaj lafwa ou. Sa depase nati imen e montre pouvwa Lespri Bondye ki travay nan ou.", prayer: "Senyè, ban m fòs pou beni moun ki pèsekite m. Kite repons mwen toujou se benediksyon, pa madichon. Amèn.", date: "" },
  { id: "355", verse: "Benediksyon pou moun ki swaf pou jistis, paske yo pral satisfè.", reference: "Matye 5:6b", devotional: "Swaf pou jistis se yon dezi Bondye ba ou. Li pwomèt satisfè moun ki gen dezi sa a. Kontinye chache jistis ak detèminasyon e Bondye ap satisfè ou.", prayer: "Papa, ban m grangou ak swaf pou jistis ou. Mwen fè ou konfyans pou satisfè dezi sa a nan lavi m. Amèn.", date: "" },
  { id: "356", verse: "Mwen va akonpli plan mwen gen pou nou, mwen va fè tout sa mwen te di.", reference: "Ezayi 46:11", devotional: "Lè Bondye di yon bagay, li fè li. Pa gen yon pawòl li ki tonbe vid. Plan li pou ou ap reyalize e pwomès li ap akonpli. Fè li konfyans totalman.", prayer: "Senyè, mwen kwè ou ap akonpli plan ou gen pou mwen. Pawòl ou pa janm tonbe vid. Amèn.", date: "" },
  { id: "357", verse: "Mwen kapab fè plis pase sa nou mande oswa panse, dapre pouvwa ki travay nan nou.", reference: "Efezyen 3:20", devotional: "Bondye pa limite a sa ou ka imajine. Li ka fè plis, pi lwen e pi gran pase tout sa ou ka mande oswa panse. Pouvwa li travay nan ou e li pa gen limit.", prayer: "Papa, fè plis pase sa m ka mande oswa panse. Pouvwa ou nan mwen pa gen limit. Mwen fè ou konfyans. Amèn.", date: "" },
  { id: "358", verse: "Ou merite, Senyè Bondye nou, pou resevwa glwa ak onè ak pouvwa.", reference: "Revelasyon 4:11", devotional: "Bondye merite tout glwa, onè ak pouvwa. Li se Kreyatè tout bagay e tout sa ki egziste la pou volonte li. Bay li lwanj li merite.", prayer: "Senyè Bondye, ou merite tout glwa, onè ak pouvwa. Mwen ba ou lwanj ak adorasyon. Amèn.", date: "" },
  { id: "359", verse: "M ap fè yon alyans lapè ak yo; se yon alyans ki p ap janm fini.", reference: "Ezekyèl 37:26", devotional: "Bondye fè yon alyans lapè ak ou ki p ap janm fini. Se pa yon kontra tanporè men yon angajman etènèl. Ou an sekirite nan alyans li pou tout tan.", prayer: "Senyè, mèsi pou alyans lapè ou ki p ap janm fini. Mwen viv nan sekirite kontra etènèl ou. Amèn.", date: "" },
  { id: "360", verse: "Vin jwenn mwen nou tout ki bouke e ki chaje, e m a ba nou repo.", reference: "Matye 11:28c", devotional: "Envitasyon Jezi a toujou ouvè. Nenpòt lè ou bouke, nenpòt lè ou chaje, vini. Li p ap janm refize ou. Repo li disponib pou ou kounye a menm.", prayer: "Jezi, mwen vini bò kote ou jodi a, bouke e chaje. Ban m repo ou. Mèsi ke pòt ou toujou ouvè. Amèn.", date: "" },
  { id: "361", verse: "Mwen konnen plan m gen pou nou, plan pou ban nou lapè e pa pou fè nou mal.", reference: "Jeremi 29:11c", devotional: "Plan Bondye pou ou se lapè, pa mal. Li pa janm planifye destriksyon ou men restorasyon ou. Menm nan moman difisil, plan li toujou pou byen ou.", prayer: "Papa, mèsi ke plan ou pou mwen se lapè e pa mal. Mwen fè ou konfyans ak tout avni m. Amèn.", date: "" },
  { id: "362", verse: "Konsa, mete tout zam Bondye a sou nou pou nou ka kenbe fèm kont riz dyab la.", reference: "Efezyen 6:11", devotional: "Bondye ba ou tout zam ou bezwen pou kanpe kont riz ènmi an. Pa kite ou san pwoteksyon. Mete zam li a chak jou e kanpe fèm nan lafwa.", prayer: "Papa, ede m mete tout zam ou a chak jou. Mwen vle kanpe fèm kont tout riz ènmi an. Amèn.", date: "" },
  { id: "363", verse: "Gade, mwen kanpe nan pòt la e m ap frape. Si yon moun tande vwa m e louvri pòt la, m ap antre.", reference: "Revelasyon 3:20", devotional: "Jezi kanpe nan pòt kè ou e l ap frape. Li pa fòse antre men li tann ou envite li. Louvri pòt kè ou ba li jodi a e l ap antre nan yon kominyon dous.", prayer: "Jezi, mwen tande ou ap frape. Mwen louvri pòt kè m pou ou. Antre e rete avèk mwen. Amèn.", date: "" },
  { id: "364", verse: "Men, gras Bondye ki ban nou laviktwa pa Senyè nou Jezikri.", reference: "1 Korentyen 15:57", devotional: "Viktwa final la se pa travay nou men kado Bondye. Gras a Jezikri, nou gen laviktwa sou peche, lanmò ak tout sa ki mal. Remèsye Bondye pou viktwa sa a.", prayer: "Papa, mèsi pou laviktwa ou ban mwen pa Jezi. Mwen genyen pa gras ou, pa pa fòs mwen. Amèn.", date: "" },
  { id: "365", verse: "Wi, mwen vini talè konsa! Amèn! Vini, Senyè Jezi!", reference: "Revelasyon 22:20", devotional: "Dènye pawòl Bib la se yon pwomès ak yon envitasyon. Jezi ap vini talè e repons nou se yon envitasyon ak kè kontan: Vini, Senyè Jezi! Viv ak espwa retou li.", prayer: "Senyè Jezi, vini! Mwen tann retou ou ak kè kontan e espwa. Amèn, vini talè! Amèn.", date: "" },
];
